(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["pl"] = {"ui":{"skip":"Przejdź do treści","back":"← Wróć do AI-gile","lang.button":"Język: {name}","lang.dialog":"Wybierz język","lang.search":"Szukaj języków","lang.none":"Nie znaleziono języka","lang.notYet":"{name} nie jest jeszcze przetłumaczony","theme.aria":"Przełącz motyw: jasny, ciemny lub czarny","theme.toLight":"Przełącz na jasny motyw","theme.toDark":"Przełącz na ciemny motyw","theme.toBlack":"Przełącz na czarny motyw (prawdziwa czerń, przyjazna ekranom OLED)","words.underline":"Podkreśl te słowa na stronie","words.underlineHelp":"Najedź kursorem na słowo z kropkowanym podkreśleniem albo je dotknij, żeby zobaczyć, co znaczy.","words.col.todo":"Karty wybrane na teraz: zespół zabierze się za nie w następnej kolejności.","words.col.doing":"Jedna AI pracuje nad tą kartą właśnie teraz.","words.col.review":"Jedna AI skończyła pracę; zanim trafi do Ciebie, sprawdza ją druga.","words.col.verify":"Czeka na Ciebie: wypróbuj i daj znać, czy działa.","words.col.team":"Twoje notatki lub odpowiedzi, czekające, aż zespół je odbierze.","words.col.done":"Zakończone i zaakceptowane.","index.title":"AI-gile: Twój zespół AI do programowania, na jednej tablicy","index.description":"AI-gile to tablica kanban dla zespołów programistycznych AI. Pracują, gdy Ty śpisz; Ty dostajesz jeden krótki stos spraw do rozstrzygnięcia, przetestowania i zaakceptowania.","hero.logoAlt":"Ikona tablicy AI-gile","hero.h1.html":"Twój zespół AI do programowania, na jednej&nbsp;tablicy.","hero.alpha":"🐣 Zamknięta pre-alfa","hero.alphaTitle":"Wczesna i niedokończona: dzięki, że próbujesz!","hero.lede":"Budują, gdy śpisz. Budzisz się przy jednym krótkim stosie: kilka pytań, kilka rzeczy do przetestowania, fioletowy diament czy dwa. Klik, akceptacja i z powrotem do kawy.","dl.windows":"Aplikacja na Windows","dl.browser":"Uruchom w przeglądarce","dl.messenger":"📱 Messenger na telefon","dl.soon":"Wkrótce","dl.notify":"🔔 Powiadom mnie, gdy ruszy","dl.notifySmall":"Alfa lub beta","hero.secondary":"Agile, ale zespół nigdy nie potrzebuje kawy na stojąco. (I tak robią stand-upy.)","pitch.h2":"AI-gile w tylu słowach, ilu chcesz","pitch.lede":"Wybierz długość, od jednego słowa do 144. Każda długość to osobny opis, napisany właśnie na ten rozmiar. Przeciągnij suwak albo użyj strzałek.","pitch.rangeLabel":"Długość w słowach","pitch.dice":"🎲 inna wersja","pitch.words.one":"{n} słowo","pitch.words.other":"{n} słowa","pitch.letters.one":"{n} litera","pitch.letters.other":"{n} litery","pitch.chars.one":"{n} znak","pitch.chars.other":"{n} znaku","count.line.html.one":"{n} karta na tablicy w tej chwili","count.line.html.other":"{n} karty na tablicy w tej chwili","people.humans.html.one":"👥 {n} osoba","people.humans.html.other":"👥 {n} osób","people.agents.html.one":"🤖 {n} agent","people.agents.html.other":"🤖 {n} agentów","people.working.html.one":"⚡ {n} w pracy w tej chwili","people.working.html.other":"⚡ {n} w pracy w tej chwili","pre.title":"AI-gile: coś tu powstaje","pre.description":"Coś tu powstaje: tablica, na której zespoły AI budują to, o co prosisz, i przy okazji cię uczą. Na razie zamknięta pre-alfa z przyjaciółmi.","pre.h1":"Coś tu powstaje. 🤫","pre.line":"Tablica, na której zespoły AI budują to, o co prosisz, i przy okazji cię uczą. Na razie zamknięta pre-alfa z przyjaciółmi.","pre.btn":"🔔 Powiadom mnie, gdy ruszy","pre.peek":"Za szybą: prawdziwa tablica, na żywo. Każda karta to kolorowy pasek.","pre.peekFake":"Za szybą: tak wygląda tablica w akcji.","pre.night":"🌙 Nocny stróż trzyma pieczę nad wszystkim · 😴 człowiek odpoczywa","features.aria":"Co robi","f.pile.h":"Jeden stos dla Ciebie","f.pile.html":"<b>Dla Ciebie</b> zbiera wszystko, co czeka na Ciebie, we wszystkich projektach: pytania, rzeczy do przetestowania, zadania tylko dla człowieka. Twoja kolejka mówi, co dalej i ile to zajmie.","f.sleep.h":"Zespoły, które pracują, gdy śpisz","f.sleep.p":"Każdy projekt ma lidera i zespół agentów AI. Skomentuj kartę, a zespół się budzi, robi swoje i oddaje ją z krokami, które zrozumie zmęczony człowiek.","f.tester.h":"Najpierw sprawdza tester AI","f.tester.p":"Zanim cokolwiek do Ciebie trafi, tester wykonuje kroki w kopii aplikacji i pokazuje, co zobaczył, ze zrzutem ekranu. Przejrzyj te, które przeszły, i zaakceptuj jednym kliknięciem.","f.proof.h":"Dowody, nie obietnice","f.proof.p":"Każde przekazanie pokazuje, co się zmieniło: pliki, diff, zrzuty ekranu. Bez otwierania każdej aplikacji, żeby sprawdzić, czy już gotowe.","f.chat.h":"Rozmawiaj ze swoimi liderami","f.chat.p":"Pasek w stylu Discorda: jedna ikona na projekt, fioletowe diamenty przy tym, co czeka na Ciebie. Napisz do lidera pomysł; zamieni go w karty i plan, z przyciskiem ✅ Go.","f.tidy.h":"Sam dba o porządek","f.tidy.p":"Powiązane karty zlewają się w jedną, zagmatwane tytuły są poprawiane, a kontrola tokenów utrzymuje kod szczupłym. Mniej rzeczy do przełączania, mniej do myślenia.","f.private.h":"Twoje, na Twoim komputerze","f.private.li1":"Tablica działa na Twojej własnej maszynie i odpowiada tylko Tobie.","f.private.li2":"Prywatne wiadomości między ludźmi są szyfrowane od końca do końca.","f.private.li3":"Bez kont, bez trackerów, bez ciasteczek.","f.lang.h":"W Twoim języku","f.lang.p":"Ponad 120 języków, od niderlandzkiego, walijskiego i japońskiego po piracki, Yodę i klingoński, z szybkim przełącznikiem na angielski dla żargonu branżowego.","f.service.h":"Od pomysłu do prawdziwej usługi","f.service.p":"Udało Ci się zbudować z AI coś, z czego ludzie już korzystają? Oznacz to jako usługę, a tablica pomoże Ci dobrze ją prowadzić: sprawdzanie dostępności, publiczna strona statusu, incydenty z opisem, zmiany, które wymagają Go, kopie zapasowe sprawdzane codziennie. Pomoc uczy każdego kroku po drodze.","msgr.h2":"AI-gile Messenger: Twój zespół w kieszeni","msgr.p1":"Rozmawiaj ze swoim zespołem AI bez otwierania tablicy. Czatuj z liderami projektów i znajomymi, przeglądaj kroki testowe kart i odpowiadaj na nie, wszystko z telefonu.","msgr.p2":"Aby go sparować, zeskanuj kod QR na swojej tablicy. Pierwszy raz? Przyjazny czat demo wszystko Ci pokaże.","msgr.when":"Najpierw Android, potem wersja przeglądarkowa na telefony i iPhone.","msgr.who":"Twój lider projektu","msgr.b1":"Poprawka trybu ciemnego jest gotowa. Podesłać kroki testowe?","msgr.b2":"Tak, poproszę!","msgr.b3":"1. Otwórz Ustawienia. 2. Wybierz Ciemny. Wygląda dobrze?","tl.aria":"Oś czasu od pierwszej rozmowy do planów","tl.h2":"Od pierwszej rozmowy do tego, co dalej","tl.lede":"Prawdziwe daty i godziny, w Twojej strefie czasowej. Po dzisiejszym dniu to plan, bez obiecywanych dat.","tl.today":"Dziś","tl.planned":"w planach","tl.doing":"w toku","tl.cards.one":"{n} karta","tl.cards.other":"{n} karty","join.h2":"Dołącz","join.lede":"AI-gile budują brodaty dziwak z AuDHD i kilkoma bitwami o zdrowie psychiczne oraz bardzo wielu cierpliwych agentów. Na razie jest prywatne, w zamkniętej alfie z przyjaciółmi. Chcesz spróbować, gdy się otworzy?","join.btn":"Zgłoś zainteresowanie","join.small":"Napiszemy do Ciebie e-mailem i nic więcej","footer.tag":"AI-gile. Bez trackerów, bez ciasteczek, bez kawy na stojąco.","footer.licence":"Licencja biznesowa","footer.status":"Status","footer.privacy":"Co przechowujemy","footer.thanks":"Rozmowy dzięki ChilledChat","form.sending":"Wysyłanie…","form.failed":"Nie udało się: spróbuj ponownie później.","form.offline":"Nie można połączyć się z AI-gile: spróbuj ponownie później.","form.keep":"Używamy tego tylko po to, żeby Ci odpowiedzieć, a potem to usuwamy. Bez trackerów, bez ciasteczek.","form.keepLink":"Co przechowujemy","interest.title":"AI-gile: powiadom mnie, gdy ruszy alfa","interest.description":"Zostaw e-mail, żeby dowiedzieć się, kiedy ruszy zamknięta alfa lub beta AI-gile.","interest.h1":"🔔 Powiadom mnie, gdy ruszy","interest.lede":"AI-gile jest w zamkniętej pre-alfie. Zostaw e-mail, a napiszemy raz, gdy znajdzie się dla Ciebie miejsce.","interest.email":"Twój e-mail","interest.which":"Który test?","interest.alpha":"Zamknięta alfa: wcześnie, surowo, dużo zmian","interest.beta":"Beta: spokojniej, później","interest.both":"Obojętnie, co pierwsze","interest.submit":"Zapisz mnie na listę","interest.thanks":"Dzięki! Jesteś na liście.","licence.title":"AI-gile: licencja biznesowa","licence.description":"Używasz AI-gile w firmie? Poproś o bezpłatną licencję biznesową.","licence.h1":"📜 Licencja biznesowa","licence.lede":"Używasz AI-gile w pracy? Napisz, kim jesteś i czym się zajmujesz. Jeśli robi to coś dobrego, licencja jest bezpłatna.","licence.company":"Firma","licence.website":"Strona internetowa","licence.what":"Czym się zajmujesz","licence.how":"Jak to pomaga światu","licence.email":"E-mail","licence.submit":"Wyślij wniosek","licence.thanks":"Dzięki! Odpowiemy e-mailem.","status.title":"Status AI-gile","status.h1":"Status AI-gile","status.quiet":"Wszystko spokojnie","status.intro":"Czy AI-gile teraz działa? Ta strona co 5 minut sprawdza stronę internetową, udostępnianie tablic, rozmowy i pobieranie.","status.up":"Działa (odpowiedź w {ms} ms)","status.slow":"Brak odpowiedzi przy ostatnim sprawdzeniu, ponawiam","status.down":"Nie działa: brak odpowiedzi przy dwóch ostatnich sprawdzeniach","status.svc.web":"Strona internetowa","status.svc.web.offers":"Ta strona: czym jest AI-gile i formularz zgłoszeniowy","status.svc.boards":"Udostępnianie tablic","status.svc.boards.offers":"Publiczne tablice, wiadomości między znajomymi i zaproszenia","status.svc.calls":"Rozmowy","status.svc.calls.offers":"Głos, wideo i udostępnianie ekranu w AI-gile","status.svc.download":"Pobieranie","status.svc.download.offers":"Instalator na Windows i linki z zaproszeniami","status.checking":"Sprawdzanie…","status.offline":"Nie można teraz połączyć się z usługą statusu (ponawiam)","status.updated":"zaktualizowano {ago}","status.justNow":"przed chwilą","status.min":"{n} min temu","status.hours":"{n} godz. temu","status.days":"{n} dni temu","privacy.title":"AI-gile: co przechowujemy","privacy.h1":"Co przechowujemy","privacy.lede":"W skrócie: tylko to, co nam wyślesz, i nie na długo.","privacy.only":"Tylko to, co nam wyślesz: to, co wpiszesz w formularz, na przykład Twój e-mail. Nic więcej o Tobie.","privacy.sealed":"Dane są zapieczętowane, więc nasz serwer nie może ich odczytać: w Twojej przeglądarce, zanim zostaną wysłane (w starszej przeglądarce w chwili, gdy dotrą). Otworzyć je może tylko nasza własna tablica.","privacy.server":"Usuwamy je z serwera, gdy tylko dotrą do naszej tablicy. Wszystko, co leży tam dłużej niż 30 dni, i tak zostaje usunięte.","privacy.board":"Trzymamy je na naszej tablicy tylko do czasu, aż Ci odpowiemy, a potem usuwamy je również stamtąd.","privacy.none":"Bez trackerów, bez ciasteczek, bez analityki.","privacy.local":"Twój język i wybór jasnego lub ciemnego motywu zostają w Twojej przeglądarce. Nigdy nie są do nas wysyłane.","privacy.ask":"Chcesz, żeby zniknęły wcześniej? Odpowiedz na naszego e-maila i daj znać.","live.h2":"Zobacz, jak to powstaje, na żywo","live.caption":"Każda karta jest ukryta: widzisz kształt pracy, a nie słowa.","live.watching.one":"na żywo: ogląda {n}","live.watching.other":"na żywo: oglądają {n}","live.last.now":"Ostatnia karta przesunięta przed chwilą","live.last.min.one":"Ostatnia karta przesunięta {n} min temu","live.last.min.other":"Ostatnia karta przesunięta {n} min temu","live.last.hour.one":"Ostatnia karta przesunięta {n} godz. temu","live.last.hour.other":"Ostatnia karta przesunięta {n} godz. temu","live.last.day.one":"Ostatnia karta przesunięta {n} dzień temu","live.last.day.other":"Ostatnia karta przesunięta {n} dni temu","live.offline":"Tablica na żywo bierze krótki oddech. Zajrzyj wkrótce ponownie.","live.cols":"Backlog|Do zrobienia|W toku|Zespół sprawdza|Do przetestowania przez Ciebie|Dla zespołu|Gotowe","pitch.words.few":"{n} słowa","pitch.words.many":"{n} słów","pitch.letters.few":"{n} litery","pitch.letters.many":"{n} liter","pitch.chars.few":"{n} znaki","pitch.chars.many":"{n} znaków","count.line.html.few":"{n} karty na tablicy w tej chwili","count.line.html.many":"{n} kart na tablicy w tej chwili","tl.cards.few":"{n} karty","tl.cards.many":"{n} kart","footer.models":"AI-gile uruchamia dla ciebie modele AI. To, co mówią i robią, jest ich sprawą, więc sprawdź to, zanim zaufasz.","privacy.ai.h":"Część z AI","privacy.ai.models":"AI-gile to tablica. Pracę wykonują modele AI innych firm, takie jak Claude, Codex i Gemini, na twoich własnych kontach.","privacy.ai.check":"To, co piszą i robią, pochodzi od nich i może być błędne. Sprawdź to, zanim na tym polegniesz albo to opublikujesz.","privacy.ai.files":"Zmieniają pliki i uruchamiają polecenia w folderach, które podłączysz. Zrób kopię zapasową.","privacy.ai.send":"To, co dasz modelowi, trafia do firmy, która go prowadzi, na jej warunkach. Obowiązują warunki i koszty każdej z nich.","privacy.ai.asis":"AI-gile to wczesna wersja testowa, udostępniana w takim stanie, w jakim jest."},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Roboty.","Zlecone."]},{"n":2,"texts":["Kanban robotów.","Agenci, uporządkowani.","Pomysły, zbudowane."]},{"n":3,"texts":["Kanban dla robotów.","Pomysły stają się funkcjami.","Darmowy kanban agentów."]},{"n":5,"texts":["Tablica kanban prowadzona przez agentów.","Ty piszesz karty. Agenci budują.","Darmowe, lokalne, testowane, odrobinę zwariowane."]},{"n":8,"texts":["Darmowy kanban, w którym pracują agenci AI.","Zapisz pomysł. Agenci go zbudują. Ty akceptujesz.","Agile dla jednego człowieka i wielu cierpliwych robotów."]},{"n":13,"texts":["Tablica kanban na Twoim komputerze, gdzie karty biorą agenci AI.","Zapisz swój pomysł na karcie. Cały zespół agentów go zbuduje, a tester AI sprawdzi, czy działa.","Za darmo, bez kont, bez trackerów: tablica, trochę robotów i Ty u steru."]},{"n":21,"texts":["AI-gile to tablica kanban do pracy z agentami programistycznymi AI. Oni biorą karty; Ty testujesz i akceptujesz.","Każdy projekt dostaje lidera i zespół agentów AI. Skomentuj dowolną kartę, a zespół bierze się do pracy.","Darmowa, osobista tablica zadań, która działa na Twoim własnym komputerze, bez żadnych kont. Pracują roboty, ale to Ty decydujesz, co jest gotowe."]},{"n":34,"texts":["Wrzucasz pomysły na tablicę. Zespół agentów AI zamienia je w działające funkcje, testuje i oddaje z krokami do wypróbowania. Nic nie liczy się jako zrobione, dopóki Ty tego nie powiesz.","AI-gile to domowa tablica kanban, którą Rich zbudował przy ogromnej pomocy agentów, którymi teraz zarządza. Jest darmowa, działa na Twoim komputerze i jest dzielona z przyjaciółmi, a nie sprzedawana.","Wyobraź sobie zwykłą tablicę kanban z kolumnami od Backlogu do Gotowe, tyle że karty biorą agenci AI. Zgłaszają postępy, pytają, gdy utkną, i zawsze czekają na Twój kciuk w górę."]},{"n":55,"texts":["AI-gile to tablica kanban, na której zespół składa się z agentów AI. Każdy projekt ma lidera, który planuje pracę, i pomocników, którzy ją wykonują. Gdy funkcja jest gotowa, tester AI ją wypróbowuje i robi zrzut ekranu, a potem trafia na Twój stos. Zaakceptuj ją albo skomentuj, a oni poprawią.","Zaczęło się jako sposób jednej osoby na ogarnięcie wielu sesji programowania z AI naraz, a urosło do prawdziwej tablicy. Działa na Twojej maszynie, nie wymaga konta i nie ma trackerów. Jest darmowa dla przyjaciół i ciekawskich. Jest też niedokończona, więc spodziewaj się chropowatości i od czasu do czasu niespodzianki.","Powiedzmy sobie szczerze. Pomysły nadal musisz mieć sam i wyniki nadal musisz sprawdzać. AI-gile robi wszystko pomiędzy: trzyma karty w porządku, budzi właściwego agenta, gdy napiszesz komentarz, pokazuje dokładnie, co się zmieniło, i zbiera całą resztę w jeden krótki stos, który czeka właśnie na Ciebie."]},{"n":89,"texts":["AI-gile to darmowa tablica kanban, którą uruchamiasz na własnym komputerze. Zamiast ludzi każdy projekt ma zespół agentów AI: lidera, który zamienia Twoje pomysły w karty i plan, oraz pomocników, którzy biorą karty według priorytetu. Gdy coś jest zbudowane, tester AI wykonuje kroki testowe i pokazuje, co zobaczył. Potem całość czeka na jednym stosie zwanym Dla Ciebie. Akceptujesz albo komentujesz, a zespół próbuje jeszcze raz. Nic nie trafia do Gotowe bez Ciebie.","Kilka rzeczy, których możesz się nie spodziewać. Nocna straż uzupełnia kolumnę Do zrobienia, gdy śpisz, wybierając karty, które nie potrzebują Twojej odpowiedzi. Licznik tokenów pokazuje, ile agenci zużyli dziś i w tym tygodniu, a Tryb bez tokenów każe im przestać wydawać. Możesz pisać do przyjaciół, a prywatne wiadomości są szyfrowane od końca do końca. Tablica mówi w około 120 językach, w tym po niderlandzku, flamandzku, piracku i klingońsku. Nic z tego nie kosztuje ani grosza i nikt nie chce Ci tego sprzedać.","AI-gile to mały, osobisty projekt, a nie firma. Rich chciał opiekować się kilkoma projektami z AI bez otwierania każdej aplikacji osobno, żeby zobaczyć, co słychać, więc razem z agentami zbudował do tego tablicę, a potem tą samą tablicą zbudował resztę jej samej. Jest w zamkniętej pre-alfie, czyli działa, przeważnie, dla garstki przyjaciół. Nie ma cennika, newslettera ani planu podbijania świata. Jeśli brzmi to przydatnie, poproś o dostęp, gdy otworzy się trochę szerzej."]},{"n":144,"texts":["AI-gile to tablica kanban dla jednego człowieka i bardzo wielu agentów AI. Działa na Twoim własnym komputerze i jest całkowicie darmowa. Dodajesz projekty, a każdy projekt dostaje lidera i mały zespół. Rozmawiasz z liderem, trochę jak na Discordzie, i opisujesz swój pomysł; lider zamienia go w karty i plan, po czym czeka, aż naciśniesz Go. Zespół przechodzi przez karty według priorytetu, korzystając z prostego wiersza poleceń stworzonego dla modeli językowych. Zanim cokolwiek wróci do Ciebie, tester AI wykonuje wszystkie kroki w kopii aplikacji i dołącza zrzut ekranu tego, co zobaczył. Gotowa praca ląduje na Twoim stosie razem ze zmienionymi plikami i diffem. Akceptujesz ją albo zostawiasz komentarz, a wtedy zespół się budzi i próbuje jeszcze raz. Tylko Ty możesz przenieść kartę do kolumny Gotowe, nikt inny i nigdy.","Dzień z AI-gile, mniej więcej. Wieczorem zostawiasz kilka komentarzy: ten przycisk jest w złym miejscu, tamta lista powinna być posortowana, a czy mógłby być tryb ciemny. Idziesz spać. Agenci czytają komentarze, wprowadzają zmiany, testują je i oddają Ci wyniki. Jeśli kolumna Do zrobienia się opróżni, nocna straż uzupełnia ją kartami z backlogu, które nie potrzebują Twojej odpowiedzi. Rano czeka jeden krótki stos: kilka pytań i kilka rzeczy do wypróbowania, każda z krokami, za którymi trafi nawet niewyspana osoba, i ze zrzutem ekranu działającej wersji. Przeklikujesz wszystko, akceptujesz to, co dobre, i odsyłasz resztę. Licznik tokenów pokazuje, ile to wszystko zużyło, a Tryb bez tokenów czeka na chudsze tygodnie. Potem jesz śniadanie, w czym agenci jeszcze Ci nie pomogą.","Najpierw to, czym AI-gile nie jest. Nie jest startupem, nie jest na sprzedaż i nikt nie zbiera Twoich danych. To darmowa tablica, która działa na Twoim komputerze, bez kont, bez trackerów i bez ciasteczek. A czym jest: jednym uporządkowanym miejscem, w którym widzisz wszystkie projekty z AI naraz, z zespołem agentów robiącym karty i Tobą podejmującym decyzje. Łączy powiązane karty, poprawia zagmatwane tytuły i pilnuje, żeby kod pozostał szczupły. Mówi w około 120 językach, od niderlandzkiego i flamandzkiego po piracki i klingoński. Przyjaciele mogą do siebie pisać, prywatnie i szyfrowanie. Zbudowali ją Rich i bardzo wielu cierpliwych agentów, głównie korzystając z niej samej. Jest w zamkniętej pre-alfie, więc w niektórych miejscach bywa surowa. Jeśli brzmi to zabawnie, poproś ładnie, a może wejdziesz wcześniej."]}],"quips":{"1":"Jedno słowo. Odważnie. Może za odważnie.","3":"Trzy słowa. Już szczerzej niż większość stron produktów.","8":"Osiem słów. Nadal krócej niż stand-up.","21":"Długości to zresztą story pointy. Oczywiście, że tak.","55":"Pięćdziesiąt pięć słów. Dwie karty skończyły się, gdy to czytasz.","144":"To ta długa. Nie ma 233. Agenci poszli spać."}},"timeline":{"first-idea.name":"Pierwszy pomysł","first-idea.line":"Najpierwsza rozmowa, zanim powstała choćby linijka kodu.","first-board.name":"Pierwsza tablica","first-board.line":"Tablica, która śledzi własną budowę: karty, kolumny, przeciąganie, projekty.","team-roles.name":"Zespół i role","team-roles.line":"Profile agentów, szablony zespołów, przestrzenie i kto za co odpowiada.","install.name":"Instalacja i wydania","install.line":"Zip, który przyjaciel zainstaluje, z samoaktualizacją, kanałami i cofaniem.","usage-saver.name":"Oszczędzanie zużycia","usage-saver.line":"Mierzenie kosztu uruchomień, szczupły kod, oszczędzanie limitu.","friends.name":"Przyjaciele i udostępnianie","friends.line":"Prywatne wiadomości, zaszyfrowany przekaźnik, zaproszenia, role i wspólne projekty.","languages.name":"Języki","languages.line":"Każdy tekst na ekranie w pliku językowym, na początek niderlandzki i flamandzki.","ai-tester.name":"Tester AI","ai-tester.line":"Tester sprawdza każde przekazanie jako pierwszy i pokazuje, co zobaczył.","website.name":"Strona internetowa","website.line":"aigile.lol, strona zapowiedzi i ta oś czasu.","streaming.name":"Czat i streaming","streaming.line":"Discord, Twitch, OBS, tryb streamera, GIF-y i emoji.","no-ai.name":"Wersja bez AI","no-ai.line":"Tablica dla ludzi, którzy programują bez AI, oraz tablice publiczne.","night-watch.name":"Nocna straż","night-watch.line":"Stróż i Scrum Master pilnują zespołów, gdy śpisz.","p-more.name":"Cała reszta","p-more.line":"Mniejsze pomysły, które wciąż czekają na swoją kolej.","p-android.name":"Telefon i Android","p-android.line":"Dostęp do tablicy z telefonu, a potem natywna aplikacja na Androida.","p-release.name":"Alfa i dalej","p-release.line":"Zamknięta alfa, strona na żywo, potem beta.","p-languages.name":"Więcej języków","p-languages.line":"130 języków i tryb immersji dla uczących się.","p-engines.name":"Więcej silników AI","p-engines.line":"Wybierz Claude, Codex, Gemini, Copilot albo Cursor dla każdego agenta.","p-pro.name":"Praktyka zawodowa","p-pro.line":"Etykiety ryzyka, bramki scalania, karty incydentów i bariery ochronne.","p-self.name":"Dbanie o Ciebie","p-self.line":"Tryb zmęczenia, przypomnienia o dbaniu o siebie i 4:20.","p-servers.name":"Serwery i skala","p-servers.line":"Globalne ustawienia serwera, role i planowanie wzrostu.","p-livestream.name":"Dodatki do streamów","p-livestream.line":"Czat Twitcha, własne emoji i publiczny podgląd na żywo."},"words":{"button":"📖 Żargon branżowy","h":"📖 Słowniczek","intro":"Darmowe szkolenie prostym językiem: każde słowo, które spotkasz, od pierwszego pomysłu po usługę, na której ludzie polegają, z Agile, budowaniem, dbaniem o bezpieczeństwo i pracą z AI po drodze.","search":"Szukaj słowa…","none":"Żadne słowo nie pasuje.","close":"Zamknij","count":{"one":"{count} słowo","other":"Słów: {count}"},"groups":[{"id":"idea","name":"💡 Pomysł i rozpoznanie"},{"id":"plan","name":"🗺️ Planowanie pracy"},{"id":"agile","name":"🔁 Zwinne sposoby pracy"},{"id":"build","name":"🛠️ Budowanie"},{"id":"test","name":"🧪 Testowanie i jakość"},{"id":"change","name":"🔀 Bezpieczne zmiany"},{"id":"run","name":"🛎️ Utrzymanie usługi"},{"id":"sec","name":"🔒 Bezpieczeństwo i prywatność"},{"id":"ai","name":"🤖 Praca z AI"},{"id":"money","name":"💰 Pieniądze i licencje"}],"list":[{"id":"discovery","g":"idea","word":"Discovery (rozpoznanie)","text":"Wczesny etap, w którym ustala się, jaki problem warto rozwiązać i dla kogo, zanim cokolwiek powstanie.","also":["rozpoznanie","faza discovery","discovery phase"]},{"id":"problemstmt","g":"idea","word":"Opis problemu","text":"Jedno lub dwa zdania o tym, kto ma problem, na czym polega i dlaczego jest ważny, żeby wszyscy mierzyli w to samo.","also":["opisy problemu","problem statement"]},{"id":"user","g":"idea","word":"Użytkownik","text":"Osoba, która korzysta z tego, co budujesz. Jej potrzeby są powodem, dla którego w ogóle pracujesz.","also":["użytkownicy","user"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Interesariusz","text":"Każdy, komu zależy na tym, jak praca się skończy, albo kogo ona dotyczy, na przykład ci, którzy za nią płacą, z niej korzystają albo ją wspierają.","also":["interesariusze","stakeholder"]},{"id":"persona","g":"idea","word":"Persona","text":"Wymyślona, ale realistyczna osoba, która reprezentuje jeden rodzaj użytkowników, żeby zespół mógł zapytać: „Czy Kasia uzna to za proste?”","also":["persony"]},{"id":"userresearch","g":"idea","word":"Badania użytkowników","text":"Rozmawianie z prawdziwymi ludźmi i obserwowanie ich, żeby dowiedzieć się, czego potrzebują, zamiast zgadywać.","also":["wywiady z użytkownikami","user research","user interviews"]},{"id":"journey","g":"idea","word":"Ścieżka użytkownika","text":"Kroki, które człowiek wykonuje, żeby coś załatwić, od pierwszej wzmianki aż po koniec, także poza Twoim produktem. Narysowanie ich pokazuje, gdzie ludzie się zacinają.","also":["ścieżki użytkownika","customer journey","user journey","mapa podróży klienta"]},{"id":"painpoint","g":"idea","word":"Punkt bólu","text":"Coś, co dziś irytuje ludzi albo ich spowalnia. Dobre produkty usuwają takie bolączki.","also":["punkty bólu","bolączka","pain point"]},{"id":"assumption","g":"idea","word":"Założenie","text":"Coś, w co wierzysz, ale czego jeszcze nie sprawdzono. Spisanie założeń pokazuje, co przetestować najpierw.","also":["założenia","assumption"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Hipoteza","text":"Najlepsze przypuszczenie, które planujesz sprawdzić, razem z tym, czego się spodziewasz, na przykład: „ludzie się zarejestrują, jeśli pierwszy miesiąc będzie za darmo”.","also":["hipotezy","hypothesis"]},{"id":"experiment","g":"idea","word":"Eksperyment","text":"Mały, zaplanowany test, który pokazuje, czy pomysł działa, zanim dużo na niego postawisz.","also":["eksperymenty","experiment"],"noTip":1},{"id":"poc","g":"idea","word":"Proof of concept (PoC)","text":"Szybka, surowa próba, żeby zobaczyć, czy pomysł w ogóle może zadziałać. Zwykle wyrzuca się ją, gdy znasz już odpowiedź.","also":["PoC","proof of concept","dowód koncepcji"]},{"id":"prototype","g":"idea","word":"Prototyp","text":"Wczesny model produktu, często klikalne obrazki, żeby wypróbować pomysł na ludziach, zanim zbudujesz go porządnie.","also":["prototypy","prototype"]},{"id":"wireframe","g":"idea","word":"Wireframe (szkic ekranu)","text":"Prosty szkic ekranu pokazujący, co gdzie stoi, bez kolorów i prawdziwej zawartości.","also":["wireframe","szkic ekranu","makieta szkicowa"]},{"id":"mockup","g":"idea","word":"Makieta","text":"Dokładny obrazek tego, jak ekran będzie wyglądał, z prawdziwymi kolorami i tekstem, ale na razie nic nie działa.","also":["makiety","mockup","mockupy","mock-up"]},{"id":"bizcase","g":"idea","word":"Uzasadnienie biznesowe","text":"Powody, dla których warto robić projekt: ile kosztuje, ile przynosi albo oszczędza i jakie niesie ryzyka.","also":["business case","biznesplan"]},{"id":"feasibility","g":"idea","word":"Wykonalność","text":"Czy da się to naprawdę zbudować i utrzymać przy czasie, pieniądzach i umiejętnościach, które masz.","also":["wykonalny","feasibility"]},{"id":"outcome","g":"idea","word":"Efekt (outcome)","text":"Zmiana, jakiej chcesz dla ludzi, na przykład mniej odwołanych wizyt. Liczy się bardziej niż to, ile zbudujesz.","also":["efekty","rezultat","outcome"],"noTip":1},{"id":"output","g":"idea","word":"Wytwór (output)","text":"Coś, co zespół robi, na przykład nowy ekran albo raport. To, że powstało, nie znaczy jeszcze, że komuś pomaga.","also":["wytwory","output"],"noTip":1},{"id":"successmetric","g":"idea","word":"Miara sukcesu","text":"Liczba, która mówi, czy praca spełniła swój cel, na przykład więcej osób kończących zamówienie.","also":["miary sukcesu","success metric"]},{"id":"kpi","g":"idea","word":"Kluczowy wskaźnik efektywności (KPI)","text":"Ważna liczba, na którą patrzysz, żeby wiedzieć, czy idzie dobrze, na przykład rejestracje w tygodniu.","also":["KPI","wskaźnik KPI","key performance indicator"]},{"id":"okr","g":"idea","word":"Cele i kluczowe rezultaty (OKR)","text":"Sposób wyznaczania celów: cel mówi, czego chcesz, a kilka kluczowych rezultatów to liczby, które pokazują, że się udało.","also":["OKR","OKRy","objectives and key results"]},{"id":"product","g":"plan","word":"Produkt","text":"To, co się buduje i utrzymuje dla użytkowników, na przykład aplikacja, strona albo narzędzie.","also":["produkty","product"],"noTip":1},{"id":"vision","g":"plan","word":"Wizja produktu","text":"Krótkie stwierdzenie, komu produkt pomaga i dokąd zmierza w dłuższej perspektywie.","also":["wizja","product vision","vision statement"]},{"id":"po","g":"plan","word":"Product Owner (PO)","text":"Osoba, która decyduje, co się buduje i w jakiej kolejności, żeby zespół zawsze pracował nad tym, co najważniejsze. W AI-gile to Ty.","also":["PO","product owner","właściciel produktu"]},{"id":"pm","g":"plan","word":"Product Manager (PM)","text":"Osoba, która dba o kierunek produktu: jakie problemy rozwiązuje, dla kogo i po co. PM może też znaczyć kierownik projektu, więc sprawdź, o co chodzi.","also":["PM","product manager","menedżer produktu"]},{"id":"projmgr","g":"plan","word":"Kierownik projektu","text":"Osoba, która pilnuje, żeby projekt zmieścił się w czasie i budżecie, i śledzi, kto co robi i na kiedy.","also":["kierownicy projektów","project manager","menedżer projektu"]},{"id":"roadmap","g":"plan","word":"Roadmapa","text":"Zgrubny plan tego, co przyjdzie w najbliższych miesiącach, po kolei. Pokazuje kierunek, a nie dokładne daty, i zmienia się w miarę, jak dowiadujesz się więcej.","also":["mapa drogowa","roadmap","roadmapy"]},{"id":"milestone","g":"plan","word":"Kamień milowy","text":"Punkt w projekcie, który warto zaznaczyć, na przykład „pierwsza wersja działa” albo „100 użytkowników”.","also":["kamienie milowe","milestone"]},{"id":"mvp","g":"plan","word":"Minimum viable product (MVP)","text":"Najmniejsza wersja produktu, która nadal jest przydatna prawdziwym ludziom, żeby uczyć się od nich jak najwcześniej.","also":["MVP","minimalny produkt","minimum viable product"]},{"id":"requirement","g":"plan","word":"Wymaganie","text":"Coś, co gotowy produkt musi robić albo czym musi być.","also":["wymagania","requirement"],"noTip":1},{"id":"scope","g":"plan","word":"Zakres","text":"Co wchodzi w skład pracy i, co równie ważne, co nie wchodzi.","also":["w zakresie","poza zakresem","scope"]},{"id":"scopecreep","g":"plan","word":"Pełzający zakres (scope creep)","text":"Gdy do pracy dokłada się coraz więcej po trochu, bez zgody na dodatkowy czas czy koszt, więc nigdy nie jest całkiem skończona.","also":["scope creep","feature creep","rozrost zakresu"]},{"id":"feature","g":"plan","word":"Funkcja","text":"Jedna rzecz, którą produkt potrafi zrobić dla ludzi, na przykład „zresetuj hasło”.","also":["funkcje","funkcjonalność","feature"],"noTip":1},{"id":"epic","g":"plan","word":"Epik (epic)","text":"Duży kawał pracy, za duży na jeden raz, więc dzieli się go na mniejsze karty.","also":["epiki","epic","epics"]},{"id":"story","g":"plan","word":"Historyjka użytkownika (user story)","text":"Mały kawałek pracy opisany z perspektywy użytkownika: „Jako kupujący chcę zapisać koszyk, żeby dokończyć później”. Zaczyna rozmowę o tym, co zbudować.","also":["historyjki użytkownika","user story","user stories"]},{"id":"ac","g":"plan","word":"Kryteria akceptacji (AC)","text":"Sprawdziany, które jedna karta musi przejść, by uznać ją za skończoną, uzgodnione przed startem pracy, na przykład „koszyk nadal jest po wylogowaniu i ponownym zalogowaniu”.","also":["AC","acceptance criteria"]},{"id":"task","g":"plan","word":"Zadanie","text":"Pojedyncza rzecz do zrobienia, często jeden mały krok większej historyjki.","also":["zadania","task","tasks"],"noTip":1},{"id":"ticket","g":"plan","word":"Zgłoszenie (ticket)","text":"Inne słowo na kartę: jedna porcja pracy albo jedna prośba, śledzona od początku do końca.","also":["zgłoszenia","ticket","tickets","bilet"]},{"id":"priority","g":"plan","word":"Priorytet","text":"Jak ważna albo pilna jest sprawa w porównaniu z resztą, żeby to, co najważniejsze, robić najpierw.","also":["priorytety","priority"],"noTip":1},{"id":"prioritise","g":"plan","word":"Priorytetyzacja","text":"Układanie pracy według ważności. Częsty sposób to MoSCoW: Must have (musi być), Should have (powinno być), Could have (mogłoby być), Won’t have (tym razem nie).","also":["ustalanie priorytetów","priorytetyzować","MoSCoW"]},{"id":"estimate","g":"plan","word":"Szacunek","text":"Najlepsze przypuszczenie, jak duża albo jak długa jest jakaś praca. To przypuszczenie, nie obietnica.","also":["szacunki","szacowanie","estimate","estimation"],"noTip":1},{"id":"storypoints","g":"plan","word":"Story pointy (punkty historii)","text":"Sposób zgadywania wielkości pracy przez porównywanie kart ze sobą („mniej więcej dwa razy większa niż tamta”), a nie w godzinach. Nie służą do porównywania zespołów.","also":["story points","story point","punkty historii"]},{"id":"tshirt","g":"plan","word":"Rozmiary koszulek (T-shirt sizing)","text":"Szacowanie wielkości pracy jako S, M, L albo XL. Szybkie i wystarczające do wczesnego planowania.","also":["t-shirt sizing","t-shirt sizes","rozmiary koszulek"]},{"id":"poker","g":"plan","word":"Planning poker","text":"Gra do szacowania: wszyscy jednocześnie pokazują kartę z rozmiarem, a potem osoby z najwyższą i najniższą wyjaśniają dlaczego.","also":["Scrum poker","poker planistyczny"]},{"id":"dependency","g":"plan","word":"Zależność","text":"Gdy jedna praca nie może się zacząć ani skończyć, dopóki nie zrobi się inna.","also":["zależności","dependency","dependencies"]},{"id":"blocker","g":"plan","word":"Bloker (przeszkoda)","text":"Cokolwiek, co teraz zatrzymuje pracę, na przykład brak odpowiedzi albo zepsute narzędzie.","also":["blokery","blocker","blockers","przeszkoda"]},{"id":"deadline","g":"plan","word":"Termin","text":"Data, do której coś musi być skończone.","also":["terminy","deadline","deadlines"],"noTip":1},{"id":"deliverable","g":"plan","word":"Rezultat do przekazania","text":"Coś konkretnego, co praca wytwarza i przekazuje dalej, na przykład działająca strona albo raport.","also":["deliverable","deliverables","produkt do dostarczenia"]},{"id":"forecast","g":"plan","word":"Prognoza","text":"Przewidywanie, co prawdopodobnie się stanie, na przykład kiedy praca będzie gotowa, na podstawie tego, co dotąd wiadomo.","also":["prognozy","forecast","forecasts"],"noTip":1},{"id":"metric","g":"plan","word":"Metryka","text":"Wszystko, co mierzysz i śledzisz w czasie, na przykład odwiedziny strony albo czas naprawy błędu.","also":["metryki","wskaźnik","metric","metrics"]},{"id":"feedback","g":"plan","word":"Feedback (opinia zwrotna)","text":"To, co ludzie mówią o Twojej pracy, dobre i złe. Zbieranie tego wcześnie i często to serce Agile.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"Lista oczekujących pomysłów i prac jeszcze niezaplanowanych, z najważniejszymi na górze. Nic stamtąd nie jest robione, dopóki nie trafi do kolumny Do zrobienia."},{"id":"sprint","g":"agile","word":"Sprint","text":"Krótki, stały odcinek pracy (często jeden lub dwa tygodnie, nigdy dłużej niż miesiąc) z celem i uzgodnionym zestawem kart do skończenia.","also":["sprinty","sprint"]},{"id":"standup","g":"agile","word":"Stand-up","text":"Szybkie codzienne spotkanie: co każdy z zespołu zrobił, co robi dalej i co mu przeszkadza. W Scrumie nazywa się daily scrum.","also":["standup","stand-upy","daily scrum","daily stand-up","codzienne spotkanie"]},{"id":"kanban","g":"agile","word":"Kanban","text":"Sposób pracy, w którym karty przesuwają się przez kolumny tablicy (jak Do zrobienia, W toku, Gotowe), a zespół ogranicza, ile jest w toku naraz, żeby praca płynęła."},{"id":"wip","g":"agile","word":"Limit WIP","text":"WIP to skrót od „work in progress”, czyli praca w toku. Limit WIP to największa liczba kart, jaką kolumna powinna trzymać naraz, żeby zespół kończył rzeczy, zanim zacznie następne.","also":["WIP"]},{"id":"dod","g":"agile","word":"Definicja Zrobione","text":"Krótka lista zespołu, co znaczy „skończone”, na przykład przetestowane i wyjaśnione, zanim karta trafi do Ciebie. Jej bliźniaczka, Definicja Gotowe do startu, mówi, kiedy karta jest na tyle jasna, żeby zacząć.","also":["Definition of Done","Definition of Ready","DoD","DoR","Definicja ukończenia","Definicja gotowości"]},{"id":"retro","g":"agile","word":"Retro","text":"Regularne spojrzenie wstecz na to, jak pracuje zespół, żeby ustalić jedną czy dwie rzeczy do poprawy następnym razem. Skrót od retrospektywa. W AI-gile retro proponuje zmianę w sposobie pracy zespołu, a Ty mówisz Go albo Jeszcze nie.","also":["retrospektywa","retrospektywy"]},{"id":"swarm","g":"agile","word":"Rój","text":"Wszystkie ręce na pokład: wiele osób odkłada inną pracę i razem naprawia jedną pilną sprawę, dopóki nie zostanie załatwiona. W AI-gile każdy zespół pomaga przy jednym projekcie, a inne projekty w tym czasie czekają.","also":["tryb roju","swarm","swarming"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"W Scrumie osoba, która pomaga zespołowi dobrze pracować: usuwa to, co go blokuje, pilnuje spotkań i uczy dobrych nawyków, nikim nie rządząc. W AI-gile Lead Scrum Master wyłapuje utknięte karty, popędza zespoły i przypomina Ci, co czeka, we wszystkich projektach.","also":["Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agile (zwinne podejście)","text":"Praca małymi krokami: zbudować trochę, często pokazywać prawdziwe wyniki, uczyć się z opinii ludzi i zmieniać plan w trakcie, zamiast planować wszystko z góry.","also":["zwinne","metodyki zwinne","Agile development","agile ways of working"]},{"id":"manifesto","g":"agile","word":"Manifest Agile","text":"Krótki tekst napisany w 2001 roku przez twórców oprogramowania. Stawia ludzi, działające efekty, bliską współpracę z klientami i reagowanie na zmiany przed ciężkimi planami i papierami.","also":["Manifest zwinnego wytwarzania oprogramowania","Agile Manifesto","Manifesto for Agile Software Development"]},{"id":"waterfall","g":"agile","word":"Model kaskadowy (waterfall)","text":"Starszy sposób pracy: zaplanować wszystko, potem wszystko zbudować, potem wszystko przetestować, etap po etapie. Zmiany na późnym etapie są trudne i drogie.","also":["kaskadowo","waterfall","waterfall model"]},{"id":"iteration","g":"agile","word":"Iteracja","text":"Jedna runda budowania czegoś, sprawdzania i ulepszania. Praca w Agile to łańcuch takich rund, a sprint to jeden z ich rodzajów.","also":["iteracje","iteration","iterations"]},{"id":"increment","g":"agile","word":"Przyrost (inkrement)","text":"Nowy, działający kawałek dodany do produktu w sprincie albo rundzie pracy, który pasuje do tego, co już było.","also":["przyrosty","inkrement","increment","increments"]},{"id":"scrum","g":"agile","word":"Scrum","text":"Popularny zwinny sposób pracy: mały zespół pracuje w krótkich sprintach ku celowi, z określonymi rolami i kilkoma stałymi spotkaniami do planowania, sprawdzania i ulepszania."},{"id":"scrumteam","g":"agile","word":"Zespół Scrum","text":"Mała grupa, która robi pracę w Scrumie: Product Owner, Scrum Master i deweloperzy.","also":["zespoły Scrum","Scrum team","Scrum teams"]},{"id":"ceremonies","g":"agile","word":"Wydarzenia Scrum","text":"Stałe spotkania w Scrumie: planowanie sprintu, daily scrum, przegląd sprintu i retrospektywa. Wiele osób nazywa je ceremoniami.","also":["ceremonie","ceremonie Scruma","Scrum events","Scrum ceremonies"]},{"id":"sprintplan","g":"agile","word":"Planowanie sprintu","text":"Spotkanie na początku sprintu, na którym zespół uzgadnia, dlaczego sprint jest ważny, które karty weźmie i jak zacząć.","also":["spotkanie planujące","sprint planning","planning meeting"]},{"id":"sprintgoal","g":"agile","word":"Cel sprintu","text":"Jedno zdanie o tym, do czego służy sprint. Małe zadania mogą się po drodze zmieniać, byle cel został osiągnięty.","also":["cele sprintu","sprint goal","sprint goals"]},{"id":"sprintbacklog","g":"agile","word":"Sprint backlog","text":"Karty wybrane na bieżący sprint, razem z planem zespołu, jak je zrobić.","also":["backlog sprintu","sprint backlogs"]},{"id":"productbacklog","g":"agile","word":"Product backlog","text":"Pełna, uporządkowana lista wszystkiego, co może powstać w produkcie, z najważniejszym na górze. Zmienia się w miarę, jak dowiadujesz się więcej.","also":["backlog produktu","product backlogs"]},{"id":"productgoal","g":"agile","word":"Cel produktu","text":"Większy rezultat, do którego produkt zmierza i który pomaga zespołowi wybrać, co robić dalej.","also":["cele produktu","product goal","product goals"]},{"id":"refinement","g":"agile","word":"Doprecyzowanie backlogu","text":"Regularne przeglądanie backlogu, żeby porządkować, dzielić, ustawiać w kolejności i dopisywać szczegóły do kart, by były gotowe do podjęcia. Mówi się też grooming backlogu.","also":["refinement","backlog refinement","backlog grooming","grooming"]},{"id":"sprintreview","g":"agile","word":"Przegląd sprintu","text":"Spotkanie na końcu sprintu, na którym zespół pokazuje, co skończył, i słucha opinii ludzi, żeby zdecydować, co dalej.","also":["przeglądy sprintu","sprint review","sprint reviews"]},{"id":"demo","g":"agile","word":"Demo","text":"Pokazanie ukończonej pracy w działaniu, na żywo, osobom, które o nią prosiły.","also":["dema","pokaz","demo","demos"],"noTip":1},{"id":"timebox","g":"agile","word":"Timebox (limit czasu)","text":"Z góry ustalony czas na coś. Gdy się skończy, przerywasz, nawet jeśli nie wszystko jest zrobione.","also":["timeboxy","limit czasu","timeboxed","timeboxes"]},{"id":"velocity","g":"agile","word":"Prędkość zespołu (velocity)","text":"Ile pracy zespół zwykle kończy w sprincie, co pomaga zaplanować, ile wziąć następnym razem. To nie jest ocena tego, jak ciężko ludzie pracują.","also":["velocity","team velocity","prędkość"]},{"id":"capacity","g":"agile","word":"Moce przerobowe (capacity)","text":"Ile pracy zespół może wziąć w danym okresie, po odjęciu urlopów i innych zajęć.","noTip":1},{"id":"burndown","g":"agile","word":"Wykres spalania (burndown)","text":"Wykres pracy, która została w sprincie, opadający dzień po dniu. Jeśli linia stoi płasko, coś utknęło.","also":["burndown","burn-down chart","burndown chart","wykres burndown"]},{"id":"burnup","g":"agile","word":"Wykres postępu (burnup)","text":"Wykres skończonej pracy rosnącej w czasie, obok całości zaplanowanej, żeby widzieć, kiedy tam dojdziesz.","also":["burnup","burn-up chart","burnup chart","wykres burnup"]},{"id":"kanbanboard","g":"agile","word":"Tablica Kanban","text":"Sama tablica: kolumna na każdy etap pracy, a karty przechodzą z kolumny do kolumny.","also":["tablice Kanban","Kanban board","Kanban boards"]},{"id":"pullsys","g":"agile","word":"System ssący (pull)","text":"Sposób pracy, w którym nowa praca zaczyna się dopiero wtedy, gdy ktoś ma miejsce, żeby ją wziąć, zamiast być dokładana komuś, kto już ma pełne ręce roboty.","also":["pull system","pull-based","system pull","system ssący"]},{"id":"flow","g":"agile","word":"Przepływ (flow)","text":"Jak płynnie praca przesuwa się przez tablicę. Dobry przepływ oznacza, że karty się ruszają, a nie piętrzą.","also":["flow","przepływ pracy","flow of work"],"noTip":1},{"id":"leadtime","g":"agile","word":"Lead time (czas realizacji)","text":"Ile czasu mija od prośby o coś do tego, że jest skończone.","also":["czas realizacji","lead times"]},{"id":"cycletime","g":"agile","word":"Cycle time (czas cyklu)","text":"Ile czasu zajmuje karta od chwili, gdy naprawdę zaczyna się nad nią praca, do jej skończenia.","also":["czas cyklu","cycle times"]},{"id":"throughput","g":"agile","word":"Przepustowość (throughput)","text":"Ile kart kończy się w tygodniu albo w dowolnym ustalonym czasie.","also":["throughput","wydajność","throughput rate"]},{"id":"bottleneck","g":"agile","word":"Wąskie gardło","text":"Jeden etap, na którym praca się piętrzy i spowalnia wszystko za nim, jak wąska szyjka butelki.","also":["wąskie gardła","bottleneck","bottlenecks"]},{"id":"swimlane","g":"agile","word":"Tor (swimlane)","text":"Poziomy rząd na tablicy, który zbiera karty jednego rodzaju, na przykład pilne sprawy albo karty jednego zespołu.","also":["tory","swimlane","swimlanes","swim lane"]},{"id":"lean","g":"agile","word":"Lean (szczupłe zarządzanie)","text":"Sposób pracy, który wycina marnotrawstwo (wszystko, co nie pomaga klientowi) i dba o to, żeby praca płynęła."},{"id":"waste","g":"agile","word":"Marnotrawstwo","text":"W Lean wszystko, co kosztuje wysiłek, ale nie pomaga klientowi, na przykład czekanie, poprawki albo budowanie rzeczy, których nikt nie używa.","noTip":1},{"id":"kaizen","g":"agile","word":"Ciągłe doskonalenie","text":"Stopniowe ulepszanie się przez cały czas dzięki małym, regularnym zmianom, a potem sprawdzanie, czy pomogły. Jednym ze sposobów są retrospektywy. Mówi się też kaizen.","also":["kaizen","continuous improvement"]},{"id":"selforg","g":"agile","word":"Zespół samoorganizujący się","text":"Zespół, który sam decyduje, jak wykonać pracę, zamiast dostawać polecenia krok po kroku.","also":["samoorganizacja","samozarządzający się zespół","self-organising","self-managing team"]},{"id":"crossfunc","g":"agile","word":"Zespół międzyfunkcyjny","text":"Zespół, który ma wszystkie umiejętności potrzebne, by samodzielnie skończyć pracę, na przykład projektowanie, budowanie i testowanie.","also":["zespół wielofunkcyjny","cross-functional","cross-functional team"]},{"id":"spike","g":"agile","word":"Spike (krótkie badanie)","text":"Krótkie badanie z limitem czasu, które odpowiada na pytanie, zanim zaczniesz właściwą pracę.","also":["spike","spikes"]},{"id":"rework","g":"agile","word":"Poprawki (rework)","text":"Robienie pracy od nowa, bo za pierwszym razem nie wyszła dobrze.","also":["rework","przeróbki","reworked"]},{"id":"safe","g":"agile","word":"Scaled Agile (SAFe)","text":"Sposoby stosowania Agile w wielu zespołach w dużej organizacji. SAFe (Scaled Agile Framework) to jeden ze znanych przykładów.","also":["scaled Agile","skalowanie Agile"]},{"id":"repo","g":"build","word":"Repo","text":"Folder projektu z kodem i pełną historią commitów. Może leżeć na Twoim komputerze, na GitHubie albo w obu miejscach.","also":["repozytorium"]},{"id":"branch","g":"build","word":"Branch","text":"Osobna linia pracy w kodzie, żeby zmieniać rzeczy bez dotykania głównej wersji.","also":["branche","gałąź","gałęzie"]},{"id":"commit","g":"build","word":"Commit","text":"Zapisana migawka kodu z krótką notatką o tym, co się zmieniło. Zawsze możesz do niej wrócić.","also":["commity"]},{"id":"push","g":"build","word":"Push","text":"Wysłanie zapisanych migawek (commitów) z tego komputera do wspólnej kopii online, jak GitHub, żeby były zabezpieczone i mogli je pobrać inni."},{"id":"merge","g":"build","word":"Merge","text":"Połączenie zmian z jednej gałęzi w drugą, zwykle z powrotem do głównej wersji."},{"id":"pr","g":"build","word":"Pull request","text":"Prośba o sprawdzenie zmian z gałęzi i scalenie ich z główną wersją. Niektóre serwisy nazywają to merge request.","also":["PR","PRs","pull request","merge request"]},{"id":"refactor","g":"build","word":"Refaktoryzacja","text":"Porządkowanie kodu bez zmiany tego, co robi: mniejsze pliki, jaśniejsze nazwy, mniej powtórzeń."},{"id":"bug","g":"build","word":"Bug","text":"Coś, co nie działa tak, jak powinno.","also":["bugi","błąd","błędy"]},{"id":"peerreview","g":"build","word":"Recenzja przez innych","text":"Druga para oczu: ktoś inny niż autor sprawdza pracę, zanim trafi do Ciebie, więc mniej błędów przechodzi dalej. W AI-gile każdą kartę sprawdza inna AI.","also":["peer review","code review","przegląd kodu"]},{"id":"code","g":"build","word":"Kod","text":"Zapisane instrukcje, które mówią komputerowi, co ma robić. Nazywa się go też kodem źródłowym.","also":["kod źródłowy","source code","code"],"noTip":1},{"id":"proglang","g":"build","word":"Język programowania","text":"Język do pisania kodu, na przykład JavaScript, Python albo Java. Różne języki pasują do różnych zadań.","also":["języki programowania","programming language","programming languages"]},{"id":"developer","g":"build","word":"Programista (dev)","text":"Ktoś, kto pisze i zmienia kod. Mówi się też deweloper albo inżynier oprogramowania.","also":["dev","deweloper","programiści","developer","developers","programmer","programmers","software engineer","inżynier oprogramowania"]},{"id":"software","g":"build","word":"Oprogramowanie","text":"Programy, które działają na komputerach i telefonach, w odróżnieniu od samych urządzeń (sprzętu).","noTip":1},{"id":"app","g":"build","word":"Aplikacja","text":"Program, którego ludzie używają, żeby coś załatwić, na telefonie, komputerze albo w przeglądarce.","also":["aplikacje","app","apps","application","applications","appka"],"noTip":1},{"id":"webapp","g":"build","word":"Aplikacja webowa","text":"Aplikacja działająca w przeglądarce, więc nie trzeba niczego instalować.","also":["aplikacje webowe","web app","web apps","web application"]},{"id":"frontend","g":"build","word":"Front end","text":"Ta część aplikacji, którą widzisz i w którą klikasz: ekrany, przyciski i napisy, często w przeglądarce.","also":["frontend","front-end","warstwa frontowa"]},{"id":"backend","g":"build","word":"Back end","text":"Część aplikacji działająca za kulisami, która trzyma dane i wykonuje pracę, gdy w coś klikniesz, na przykład sprawdza Twoje hasło.","also":["backend","back-end","zaplecze"]},{"id":"fullstack","g":"build","word":"Full stack","text":"Praca zarówno nad front endem, jak i nad back endem.","also":["full-stack","fullstack"]},{"id":"ui","g":"build","word":"Interfejs użytkownika (UI)","text":"To, co człowiek widzi i czego używa na ekranie: układ, przyciski, menu i tekst.","also":["UI","user interface","interfejs"]},{"id":"ux","g":"build","word":"Doświadczenie użytkownika (UX)","text":"Jakie wrażenia daje korzystanie z czegoś: czy jest łatwe, jasne i przyjemne, czy zagmatwane i powolne.","also":["UX","user experience"]},{"id":"accessibility","g":"build","word":"Dostępność (a11y)","text":"Sprawianie, by z rzeczy mogli korzystać wszyscy, także osoby słabo widzące, niemogące używać myszy albo korzystające z czytnika ekranu.","also":["a11y","accessibility"]},{"id":"responsive","g":"build","word":"Projekt responsywny","text":"Dopasowanie stron tak, by dobrze wyglądały i działały na każdym ekranie, od telefonu po duży monitor.","also":["responsywność","RWD"]},{"id":"designsys","g":"build","word":"System projektowy","text":"Wspólny zestaw kolorów, czcionek, przycisków i zasad, żeby każdy ekran wyglądał i zachowywał się tak samo.","also":["design system","design systems","systemy projektowe"]},{"id":"architecture","g":"build","word":"Architektura","text":"Ogólny kształt systemu: jakie są główne części i jak ze sobą rozmawiają."},{"id":"database","g":"build","word":"Baza danych (DB)","text":"Uporządkowany magazyn informacji, jak bardzo mocny arkusz kalkulacyjny, który aplikacja potrafi czytać i zmieniać.","also":["baza danych","bazy danych","database","databases","DB"]},{"id":"schema","g":"build","word":"Schemat bazy danych","text":"Układ bazy danych: jakie tabele z informacjami ma i co trafia do każdej.","also":["schemat","schema"]},{"id":"sql","g":"build","word":"SQL","text":"Skrót od „structured query language”: język, którym pyta się wiele baz danych o informacje albo je zmienia.","also":["Structured Query Language","strukturalny język zapytań"]},{"id":"data","g":"build","word":"Dane","text":"Informacje przechowywane przez komputer, na przykład imiona, zamówienia albo ustawienia.","also":["data","zbiór danych","zbiory danych","dataset","datasets"],"noTip":1},{"id":"server","g":"build","word":"Serwer","text":"Komputer, który jest zawsze włączony i odpowiada na prośby innych komputerów, na przykład wysyła stronę internetową, gdy ją odwiedzasz.","also":["serwery","server","servers"]},{"id":"client","g":"build","word":"Klient","text":"Strona, która prosi serwer o coś, zwykle Twoja przeglądarka albo aplikacja. W biznesie to po prostu klient, czyli ktoś, kto kupuje.","also":["klienci","client","clients"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Skrót od „application programming interface”: ustalone menu próśb, jakie jeden program może wysłać do drugiego, jak zapytanie serwisu pogodowego o dzisiejszą prognozę.","also":["APIs","application programming interface","interfejs programistyczny"]},{"id":"endpoint","g":"build","word":"Endpoint (punkt końcowy)","text":"Jedna pozycja w menu API: adres internetowy, pod który program może się zwrócić, żeby coś dostać albo wysłać.","also":["endpointy","punkt końcowy","endpoints"]},{"id":"integration","g":"build","word":"Integracja","text":"Połączenie dwóch systemów, żeby działały razem, na przykład Twój sklep wysyła zamówienia do programu księgowego.","also":["integracje","integration","integrations"]},{"id":"webhook","g":"build","word":"Webhook","text":"Wiadomość, którą jeden system sam wysyła do drugiego w chwili, gdy coś się stanie, na przykład „płatność otrzymana”.","also":["webhooki","webhooks"]},{"id":"library","g":"build","word":"Biblioteka","text":"Gotowy kod napisany przez kogoś innego, który możesz wykorzystać zamiast pisać go samemu.","also":["biblioteki","library","libraries"],"noTip":1},{"id":"framework","g":"build","word":"Framework","text":"Gotowa struktura do budowania aplikacji, która w dużej mierze decyduje, jak kod jest ułożony, jak szkielet domu, który wypełniasz.","also":["frameworki","szkielet aplikacji","frameworks"]},{"id":"sdk","g":"build","word":"Zestaw narzędzi programistycznych (SDK)","text":"Pudełko z narzędziami, kodem i przykładami do budowania oprogramowania dla jednej platformy albo usługi.","also":["SDK","SDKs","software development kit"]},{"id":"softdep","g":"build","word":"Zależność programowa","text":"Biblioteka albo narzędzie, którego Twój kod potrzebuje do działania. Utrzymywanie ich w aktualnej wersji jest ważne dla bezpieczeństwa.","also":["zależności programowe","software dependency","software dependencies"]},{"id":"package","g":"build","word":"Pakiet","text":"Paczka gotowego kodu, którą możesz zainstalować i użyć w projekcie.","also":["pakiety","package","packages"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Menedżer pakietów","text":"Narzędzie, które pobiera i aktualizuje pakiety, od których zależy Twój kod. npm to jeden z popularnych.","also":["menedżery pakietów","package manager","package managers","npm"]},{"id":"git","g":"build","word":"Git","text":"Najpowszechniej używane narzędzie do prowadzenia historii zmian w kodzie, w postaci commitów i gałęzi."},{"id":"github","g":"build","word":"GitHub","text":"Strona, która trzyma repozytoria Gita w internecie, żeby zespoły mogły dzielić się kodem, przeglądać zmiany i śledzić pracę."},{"id":"vcs","g":"build","word":"Kontrola wersji","text":"Prowadzenie pełnej historii każdej zmiany w plikach, żeby widzieć, kto co zmienił, i móc wrócić, jeśli trzeba. Robi to Git.","also":["system kontroli wersji","version control","source control","version control system"]},{"id":"clone","g":"build","word":"Klonowanie (clone)","text":"Zrobienie własnej, pełnej kopii repozytorium, razem z historią, na swoim komputerze.","also":["klonować","sklonować","clone","cloned","cloning"]},{"id":"pull","g":"build","word":"Pull (pobranie zmian)","text":"Ściągnięcie najnowszych commitów ze wspólnej kopii (jak GitHub) na Twój komputer. Przeciwieństwo pusha.","also":["pull","git pull","pobierz zmiany"],"noTip":1},{"id":"mainbranch","g":"build","word":"Gałąź główna (main)","text":"Oficjalna wersja kodu, na której wszyscy opierają swoją pracę, często nazywana main albo master.","also":["główna gałąź","main branch","master branch","master"]},{"id":"conflict","g":"build","word":"Konflikt scalania","text":"Gdy dwie zmiany dotykają tych samych linijek na różne sposoby, więc komputer nie potrafi ich połączyć i musi wybrać człowiek.","also":["konflikty scalania","merge conflict","merge conflicts"]},{"id":"diff","g":"build","word":"Diff (różnice)","text":"Widok pokazujący dokładnie, co się zmieniło między dwiema wersjami: dodane linijki i usunięte.","also":["diff","diffs","różnice"]},{"id":"fork","g":"build","word":"Fork","text":"Twoja własna kopia cudzego repozytorium, którą możesz zmieniać, nie ruszając oryginału.","also":["forki","fork","forks","forked"]},{"id":"script","g":"build","word":"Skrypt","text":"Krótki program, który sam wykonuje jedną robotę, na przykład sprząta pliki albo uruchamia aplikację.","also":["skrypty","script","scripts"],"noTip":1},{"id":"build","g":"build","word":"Build (zbudowanie)","text":"Zamiana kodu na coś gotowego do uruchomienia albo sam gotowy do uruchomienia wynik.","also":["build","builds","buildy","budowanie"],"noTip":1},{"id":"compile","g":"build","word":"Kompilacja","text":"Przetłumaczenie kodu napisanego przez ludzi na postać, którą komputer może uruchomić bezpośrednio.","also":["kompilować","kompilator","compile","compiler"]},{"id":"cli","g":"build","word":"Wiersz poleceń (CLI)","text":"Okno tekstowe, w którym wpisujesz komputerowi polecenia zamiast klikać. Nazywa się też terminalem.","also":["wiersz poleceń","terminal","konsola","command line","command-line","CLI"]},{"id":"config","g":"build","word":"Konfiguracja (config)","text":"Ustawienia, które sterują zachowaniem oprogramowania, trzymane osobno od kodu, żeby łatwo je zmieniać.","also":["config","configuration","ustawienia"],"noTip":1},{"id":"envvar","g":"build","word":"Zmienna środowiskowa","text":"Ustawienie przekazywane programowi przy starcie, często używane na adresy albo hasła, żeby nie były wpisane w kodzie.","also":["zmienne środowiskowe","environment variable","environment variables","env var"]},{"id":"debugging","g":"build","word":"Debugowanie","text":"Tropienie, dlaczego coś nie działa, i naprawianie tego.","also":["debugować","odpluskwianie","debug","debugged","debugging"]},{"id":"pairing","g":"build","word":"Programowanie w parach","text":"Dwie osoby (albo człowiek i AI) pracują razem nad tym samym kodem: jedna pisze, druga sprawdza.","also":["pair programming","pairing","praca w parach"]},{"id":"docs","g":"build","word":"Dokumentacja (docs)","text":"Pisemne wyjaśnienia, jak coś działa albo jak z tego korzystać.","also":["dokumentacja","docs","documentation"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"Pierwszy plik do przeczytania w repozytorium: czym jest projekt i jak go uruchomić.","also":["READMEs","plik README"]},{"id":"legacy","g":"build","word":"System legacy (odziedziczony)","text":"Starszy system, który nadal jest używany i trudno go zmieniać, często dlatego, że niewiele osób jeszcze go rozumie.","also":["legacy","kod legacy","legacy system","legacy systems","legacy code"]},{"id":"techdebt","g":"build","word":"Dług techniczny","text":"Skróty, które oszczędzają czas teraz, ale spowalniają późniejsze zmiany, jak pożyczka, od której rosną odsetki. Refaktoryzacja go spłaca.","also":["technical debt","tech debt"]},{"id":"test","g":"test","word":"Test","text":"Sprawdzenie, czy coś działa tak, jak powinno. Jedne testy komputer uruchamia sam za każdym razem, gdy kod się zmienia, inne to Ty wypróbowujesz skończoną kartę, zanim ją zaakceptujesz.","also":["testy","testowanie"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Skrót od quality assurance, czyli zapewnienie jakości: wszystko, co robi się, by praca była dobra, zanim pójdzie na żywo. W AI-gile to automatyczne sprawdzenia: gdy QA jest czerwone, coś się nie udało i nie można tego wypuścić, dopóki nie zostanie naprawione.","also":["kontrola jakości","testy jakości"]},{"id":"testpile","g":"test","word":"Stos testów","text":"Gotowe karty, które czekają, aż je wypróbujesz, jedna po drugiej. Zaakceptuj jedną albo odeślij ją z notatką, a pojawi się następna.","also":["stosy testów","test pile"]},{"id":"autotest","g":"test","word":"Test automatyczny","text":"Sprawdzenie, które komputer uruchamia sam za każdym razem, gdy kod się zmienia, żeby wcześnie wyłapać błędy.","also":["testy automatyczne","automated test","automated tests","automatic tests"]},{"id":"manualtest","g":"test","word":"Test ręczny","text":"Człowiek sam sprawdza wykonaną pracę ręcznie, żeby zobaczyć, czy zachowuje się tak, jak powinna.","also":["testy ręczne","testowanie ręczne","manual test","manual tests","manual testing"]},{"id":"unittest","g":"test","word":"Test jednostkowy","text":"Mały automatyczny test jednego malutkiego kawałka kodu osobno.","also":["testy jednostkowe","unit test","unit tests"]},{"id":"integtest","g":"test","word":"Test integracyjny","text":"Sprawdzenie, czy kilka części dobrze działa razem, a nie tylko każda z osobna.","also":["testy integracyjne","integration test","integration tests"]},{"id":"endtoend","g":"test","word":"Test end-to-end (E2E)","text":"Test, który działa jak prawdziwy użytkownik od początku do końca, na przykład zakłada konto, kupuje i płaci.","also":["E2E","testy end-to-end","end-to-end tests"]},{"id":"uat","g":"test","word":"Testy akceptacyjne użytkownika (UAT)","text":"Osoby, które zamówiły pracę, same ją wypróbowują i mówią, czy robi to, czego potrzebują. Stos testów w AI-gile to właśnie taka wersja.","also":["UAT","testy akceptacyjne","acceptance testing"]},{"id":"regression","g":"test","word":"Regresja","text":"Coś, co kiedyś działało, ale zepsuło się po zmianie. Testy regresji sprawdzają, czy stare rzeczy nadal działają.","also":["regresje","test regresji","testy regresji","regression","regressions","regression test","regression tests","regression testing"]},{"id":"smoke","g":"test","word":"Smoke test (test dymny)","text":"Bardzo szybkie sprawdzenie, czy główne rzeczy w ogóle działają, na przykład zaraz po wypuszczeniu zmiany. Jeśli nie przejdzie, zatrzymaj się i sprawdź, co się stało.","also":["test dymny","testy dymne","smoke tests"]},{"id":"exploratory","g":"test","word":"Testy eksploracyjne","text":"Swobodne wypróbowywanie produktu i sprawdzanie go na różne sposoby, żeby znaleźć problemy, które pominęłyby zaplanowane sprawdziany.","also":["test eksploracyjny","exploratory testing","exploratory test","exploratory tests"]},{"id":"testcase","g":"test","word":"Przypadek testowy","text":"Jeden spisany scenariusz do wypróbowania: kroki i to, co powinno się stać.","also":["przypadki testowe","test case","test cases"]},{"id":"coverage","g":"test","word":"Pokrycie testami","text":"Jak duża część kodu jest sprawdzana przez testy automatyczne. Więcej zwykle znaczy bezpieczniej, ale samo wysokie pokrycie nie dowodzi, że działa dobrze.","also":["pokrycie kodu","test coverage","code coverage"]},{"id":"testdata","g":"test","word":"Dane testowe","text":"Wymyślone przykładowe informacje używane podczas testów, żeby nie ujawniać prywatnych danych prawdziwych osób.","also":["test data","test fixtures"]},{"id":"edgecase","g":"test","word":"Przypadek brzegowy","text":"Nietypowa sytuacja na granicy, na przykład pusty formularz albo nazwisko z apostrofem, gdzie często coś się psuje.","also":["przypadki brzegowe","edge case","edge cases"]},{"id":"happypath","g":"test","word":"Szczęśliwa ścieżka (happy path)","text":"Zwykła droga, na której wszystko idzie dobrze. Dobre testowanie sprawdza też te mniej szczęśliwe."},{"id":"perftest","g":"test","word":"Testy wydajności","text":"Sprawdzanie, jak szybko coś działa i jak radzi sobie pod obciążeniem.","also":["test wydajności","performance testing","performance test","performance tests"]},{"id":"loadtest","g":"test","word":"Testy obciążeniowe","text":"Sprawdzanie, jak system radzi sobie, gdy korzysta z niego naraz mnóstwo osób.","also":["test obciążeniowy","load testing","load test","load tests"]},{"id":"sectest","g":"test","word":"Testy bezpieczeństwa","text":"Szukanie słabych punktów, przez które ktoś mógłby nadużyć systemu albo zobaczyć to, czego nie powinien.","also":["test bezpieczeństwa","security testing","security test","security tests"]},{"id":"accesstest","g":"test","word":"Testy dostępności","text":"Sprawdzanie, czy ludzie o różnych możliwościach mogą korzystać z produktu, także z czytnikiem ekranu albo samą klawiaturą.","also":["test dostępności","accessibility testing","accessibility test"]},{"id":"linting","g":"test","word":"Linting","text":"Automatyczne sprawdzenie, które wychwytuje prawdopodobne błędy i niechlujny styl w kodzie, jak sprawdzanie pisowni dla programów.","also":["linter","lint","linterowanie"]},{"id":"static","g":"test","word":"Analiza statyczna","text":"Sprawdzanie kodu pod kątem problemów przez automatyczne przeczytanie go, bez uruchamiania.","also":["statyczna analiza kodu","static analysis","static code analysis"]},{"id":"flaky","g":"test","word":"Niestabilny test (flaky)","text":"Test, który raz przechodzi, a raz nie, bez wyraźnego powodu, więc nie można mu w pełni ufać.","also":["flaky","flaky test","flaky tests","niestabilne testy"]},{"id":"repro","g":"test","word":"Odtworzenie błędu (repro)","text":"Celowe ponowne wywołanie błędu przez wykonanie tych samych kroków, żeby można go było zbadać i naprawić. Spisanie tych kroków to najprzydatniejsza część zgłoszenia błędu.","also":["repro","reproduce","steps to reproduce","kroki do odtworzenia"]},{"id":"severity","g":"test","word":"Waga błędu (severity)","text":"Jak poważny jest skutek problemu, od drobnej uciążliwości po zatrzymanie wszystkiego.","also":["severity","poziom wagi","severity level","krytyczność"]},{"id":"deploy","g":"change","word":"Deploy","text":"Skopiowanie nowej wersji oprogramowania na komputery, które je uruchamiają, na przykład na kopię testową albo na żywą usługę."},{"id":"release","g":"change","word":"Wydanie","text":"Nazwana paczka gotowej pracy, która idzie na żywo razem, z krótkimi notatkami o tym, co się zmieniło. 🚀 Wydania pisze notatki na podstawie zrobionych kart.","also":["wydania","release"]},{"id":"rollback","g":"change","word":"Rollback","text":"Powrót do ostatniej wersji, która działała, gdy nowa sprawia kłopoty. W AI-gile ↩ Wycofaj zbiera kroki cofania zapisane przy każdej zmianie w jedną listę kontrolną.","also":["wycofanie","cofnięcie zmian","wycofać"]},{"id":"live","g":"change","word":"Na żywo","text":"Prawdziwa wersja, z której korzystają ludzie, w odróżnieniu od kopii do próbowania. Programiści mówią na nią też produkcja.","also":["produkcja","prod"],"noTip":1},{"id":"change","g":"change","word":"Zmiana","text":"Zaplanowana zmiana w czymś, na czym ludzie polegają, najpierw spisana: co, dlaczego, ryzyko, kiedy i jak ją cofnąć. Zacznij od 🔀 Zgłoś zmianę.","also":["zmiany","wniosek o zmianę","change request"],"noTip":1},{"id":"risk","g":"change","word":"Ryzyko","text":"Coś, co może pójść nie tak, ocenione według tego, jak jest prawdopodobne i jak poważne by było. ⚠️ Ryzyka trzyma je na jednej liście, od najwyższej oceny, każde z datą ponownego przejrzenia.","also":["ryzyka","rejestr ryzyk"]},{"id":"chgwin","g":"change","word":"Okno zmian","text":"Pory, w których zmiany mogą iść na żywo, na przykład spokojny wtorkowy wieczór. Poza oknem karty zmiany nie da się zakończyć, chyba że to sytuacja awaryjna.","also":["okna zmian","change window"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Ostatnie sprawdzenie tuż przed wypuszczeniem zmiany: każda osoba, która musi ją zatwierdzić, mówi Go albo No go. Zmiana idzie dalej tylko wtedy, gdy wszyscy mówią Go.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Zatwierdzenie","text":"Czekanie na „tak”, zanim praca się zacznie. Karta zgłoszona przez znajomego albo zmiana czeka w ✅ Zatwierdzeniach, aż ją zatwierdzisz albo odrzucisz.","also":["zatwierdzenia","akceptacja"]},{"id":"quiettime","g":"change","word":"Cicha pora","text":"Okres, na przykład stream na żywo, demo albo noc, w którym nic nie idzie na żywo. Zespoły dalej pracują i testują, ale wypuszczanie czeka, aż się skończy. Gdzie indziej nazywa się to zamrożeniem zmian.","also":["ciche pory","zamrożenie zmian","change freeze"]},{"id":"devops","g":"change","word":"DevOps","text":"Sposób pracy, w którym ludzie budujący oprogramowanie i ludzie, którzy je uruchamiają, są jednym zespołem i dużo automatyzują, więc zmiany trafiają na żywo często i bezpiecznie."},{"id":"cicd","g":"change","word":"CI/CD (ciągła integracja i dostarczanie)","text":"Zmiany wszystkich są często łączone z główną wersją i za każdym razem automatycznie sprawdzane (ciągła integracja), więc oprogramowanie jest zawsze gotowe do wypuszczenia jednym przyciskiem (ciągłe dostarczanie).","also":["CI/CD","CI","CD","continuous integration","continuous delivery","ciągła integracja","ciągłe dostarczanie"]},{"id":"contdeploy","g":"change","word":"Ciągłe wdrażanie","text":"Krok dalej niż ciągłe dostarczanie: każda zmiana, która przejdzie sprawdziany, trafia na żywo sama, bez przycisku do naciśnięcia.","also":["continuous deployment","continuous deployments"]},{"id":"pipeline","g":"change","word":"Pipeline (potok)","text":"Automatyczna seria kroków, przez które przechodzi zmiana w drodze na żywo, na przykład build, testy, potem wdrożenie.","also":["potok","pipeline","pipelines","pipeline CI"]},{"id":"environment","g":"change","word":"Środowisko","text":"Jedna osobna kopia systemu do jednego celu, na przykład jedna do budowania, jedna do testów i ta na żywo.","also":["środowiska","environment","environments"],"noTip":1},{"id":"devenv","g":"change","word":"Środowisko deweloperskie","text":"Kopia, w której pracuje programista, często na własnym komputerze, gdzie psucie rzeczy nikomu nie szkodzi.","also":["środowisko dev","development environment","dev environment"]},{"id":"testenv","g":"change","word":"Środowisko testowe","text":"Osobna kopia systemu używana tylko do testów, żeby nie ruszać prawdziwej usługi.","also":["środowiska testowe","test environment","test environments"]},{"id":"staging","g":"change","word":"Staging (środowisko przedprodukcyjne)","text":"Ostatnia kopia, ustawiona tak samo jak wersja na żywo, do końcowego sprawdzenia, zanim zmiana trafi do użytkowników.","also":["staging","środowisko przedprodukcyjne","staging environment"]},{"id":"artifact","g":"change","word":"Artefakt builda","text":"Plik albo paczka, którą tworzy build, gotowa do zapisania, sprawdzenia albo wypuszczenia na żywo.","also":["artefakty builda","build artifact","build artifacts","artefakt"]},{"id":"hotfix","g":"change","word":"Hotfix","text":"Pilna poprawka wypuszczona szybko, poza zwykłym planem, bo zepsuło się coś ważnego.","also":["hotfixy","hotfixes","pilna poprawka"]},{"id":"patch","g":"change","word":"Łatka (patch)","text":"Mała aktualizacja, która naprawia błąd albo zamyka dziurę w zabezpieczeniach. Szybkie instalowanie łatek bezpieczeństwa ma znaczenie.","also":["łatki","patch","patches","security patch","security patches","łatka bezpieczeństwa"]},{"id":"version","g":"change","word":"Numer wersji","text":"Etykieta jak 2.4.1, która mówi, którą wersję masz. Często pierwsza liczba zmienia się przy dużych zmianach, a ostatnia przy drobnych poprawkach.","also":["numery wersji","wersjonowanie semantyczne","version number","version numbers","semantic versioning"]},{"id":"relnotes","g":"change","word":"Notatki do wydania","text":"Krótka, prosta lista tego, co zmieniło się w wydaniu, dla ludzi, którzy z niego korzystają, razem z poprawkami i znanymi ograniczeniami. Nazywa się też changelogiem.","also":["changelog","change log","lista zmian","release notes"]},{"id":"flag","g":"change","word":"Feature flag (flaga funkcji)","text":"Włącznik i wyłącznik funkcji, dzięki któremu nowa praca może trafić na żywo ukryta, a potem zostać włączona (albo znów wyłączona) bez nowego wydania.","also":["flaga funkcji","feature flags","feature toggle","feature toggles","przełącznik funkcji"]},{"id":"rollfwd","g":"change","word":"Roll forward (naprawa do przodu)","text":"Naprawa złego wydania przez szybkie wypuszczenie nowej, poprawionej wersji zamiast wracania do starej.","also":["roll forward","rolling forward","rolled forward"]},{"id":"canary","g":"change","word":"Wydanie kanarkowe (canary)","text":"Wypuszczenie zmiany najpierw dla małej grupy, a dla wszystkich dopiero gdy wygląda dobrze. Nazwa pochodzi od kanarków, które górnicy brali pod ziemię jako wczesne ostrzeżenie.","also":["canary","canary release","canary releases","wydanie kanarkowe"]},{"id":"bluegreen","g":"change","word":"Wdrożenie blue-green","text":"Trzymanie dwóch kopii systemu na żywo i przełączenie ludzi na nową za jednym zamachem, żeby w razie kłopotów od razu wrócić.","also":["blue-green","blue green deployment","blue-green deployment"]},{"id":"zerodown","g":"change","word":"Wdrożenie bez przestoju","text":"Wypuszczenie nowej wersji tak, że usługa ani na chwilę nie przestaje działać dla użytkowników.","also":["zero downtime","zero-downtime","zero-downtime deployment"]},{"id":"chgenable","g":"change","word":"Zarządzanie zmianą","text":"Dbanie o to, żeby zmiany się udawały: ważenie ryzyka, zdobycie właściwej zgody i wybranie dobrego terminu. Mówi się też change management.","also":["change enablement","change management"]},{"id":"cab","g":"change","word":"Rada ds. zmian (CAB)","text":"Grupa, która przegląda ważne zmiany i uzgadnia, czy i kiedy mogą ruszyć.","also":["CAB","change advisory board"]},{"id":"stdchange","g":"change","word":"Zmiana standardowa","text":"Zmiana o niskim ryzyku, robiona za każdym razem w ten sam wypróbowany sposób, więc zatwierdzona z góry.","also":["zmiany standardowe","standard change","standard changes"]},{"id":"normchange","g":"change","word":"Zmiana zwykła","text":"Zmiana, którą trzeba sprawdzić i zatwierdzić, zanim ruszy.","also":["zmiany zwykłe","normal change","normal changes"]},{"id":"emergchange","g":"change","word":"Zmiana awaryjna","text":"Zmiana, która musi się stać natychmiast, żeby naprawić albo uniknąć poważnych kłopotów, z odpowiednio szybszym zatwierdzeniem.","also":["zmiany awaryjne","emergency change","emergency changes"]},{"id":"automation","g":"change","word":"Automatyzacja","text":"Zlecanie komputerowi, by sam wykonywał powtarzalną robotę, żeby było szybciej i za każdym razem tak samo.","also":["automatyzować","automation","automated"],"noTip":1},{"id":"infra","g":"change","word":"Infrastruktura","text":"Maszyny, sieci i usługi, na których działa oprogramowanie.","also":["infra","infrastructure"]},{"id":"iac","g":"change","word":"Infrastruktura jako kod (IaC)","text":"Opisanie serwerów i ustawień w plikach trzymanych razem z kodem, żeby można je było odbudować dokładnie tak samo za każdym razem.","also":["IaC","infrastructure as code"]},{"id":"cloud","g":"change","word":"Chmura","text":"Wynajmowanie komputerów, miejsca na dane i usług od dużego dostawcy przez internet zamiast posiadania maszyn.","also":["cloud","w chmurze","the cloud","cloud computing","przetwarzanie w chmurze"]},{"id":"provider","g":"change","word":"Dostawca chmury","text":"Firma wynajmująca moc obliczeniową przez internet, na przykład Amazon Web Services (AWS), Microsoft Azure albo Google Cloud.","also":["dostawcy chmury","cloud provider","cloud providers"]},{"id":"hosting","g":"change","word":"Hosting","text":"Miejsce, w którym mieszka i działa Twoja aplikacja albo strona, żeby ludzie mogli się z nią połączyć, zwykle wynajęte od firmy.","also":["hostowanie"]},{"id":"domain","g":"change","word":"Nazwa domeny","text":"Adres internetowy, który ludzie wpisują, na przykład example.com. Wynajmuje się go na rok, więc trzeba go odnawiać.","also":["domena","domeny","nazwy domen","domain name","domain names","domain"]},{"id":"dns","g":"change","word":"DNS","text":"Skrót od „domain name system”: książka adresowa internetu, która zamienia nazwę jak example.com na adres właściwego komputera.","also":["system nazw domen","domain name system"]},{"id":"container","g":"change","word":"Kontener","text":"Zamknięta paczka z aplikacją i wszystkim, czego potrzebuje, żeby działała tak samo na każdym komputerze. Docker to najbardziej znane narzędzie.","also":["kontenery","container","containers","Docker"],"noTip":1},{"id":"vm","g":"change","word":"Maszyna wirtualna (VM)","text":"Udawany komputer działający wewnątrz prawdziwego, dzięki czemu jedna duża maszyna może działać jak wiele.","also":["VM","VMs","maszyny wirtualne","virtual machine","virtual machines"]},{"id":"serverless","g":"change","word":"Serverless (bezserwerowo)","text":"Uruchamianie kodu bez dbania o jakiekolwiek serwery: dostawca uruchamia go, gdy trzeba, a Ty płacisz za to, z czego korzystasz."},{"id":"lb","g":"change","word":"Load balancer (równoważenie obciążenia)","text":"Coś, co rozkłada odwiedzających na kilka serwerów, żeby żaden z nich nie został przeciążony.","also":["load balancer","load balancers","równoważenie obciążenia"]},{"id":"cache","g":"change","word":"Cache (pamięć podręczna)","text":"Podręczny magazyn niedawnych wyników trzymany blisko, żeby nie trzeba było znów tego samego pobierać ani liczyć. Wyczyszczenie go może naprawić strony, które wyglądają na nieaktualne.","also":["cache","pamięć podręczna","cachowanie","caches","caching","cached"]},{"id":"cdn","g":"change","word":"Sieć dostarczania treści (CDN)","text":"Ogólnoświatowy zestaw serwerów trzymających kopie Twoich stron i obrazków blisko odwiedzających, żeby szybko się ładowały.","also":["CDN","content delivery network"]},{"id":"migration","g":"change","word":"Migracja","text":"Przenoszenie danych albo systemów ze starego układu do nowego albo ostrożna zmiana sposobu, w jaki ułożona jest baza danych.","also":["migracje","migracja bazy danych","migration","migrations","database migration"]},{"id":"service","g":"run","word":"Usługa","text":"Coś zbudowanego przez Ciebie, na czym ludzie polegają, na przykład strona albo aplikacja, pilnowane tak, żeby dalej działało. Zaznacz „Ten projekt jest usługą” i napisz, co oferuje, kto z niej korzysta i kto ma dyżur.","also":["usługi","serwis"]},{"id":"uptimepct","g":"run","word":"Czas działania (uptime)","text":"Jaką część czasu usługa działa, zwykle w procentach. 99,9% nadal pozwala na około 43 minuty przestoju w miesiącu.","also":["uptime","procent dostępności","uptime percentage"]},{"id":"uptime","g":"run","word":"Sprawdzanie dostępności","text":"Automatyczne sprawdzenie co kilka minut, czy Twoja usługa wciąż odpowiada. Jeśli kilka razy z rzędu się nie uda, AI-gile sam otwiera kartę incydentu.","also":["uptime","dostępność","sprawdzanie dostępności","uptime checks"]},{"id":"statuspage","g":"run","word":"Strona statusu","text":"Publiczna strona, która pokazuje, czy usługa działa (zielony, pomarańczowy albo czerwony), z najnowszą informacją, żeby jej użytkownicy mogli sprawdzić, zamiast pytać.","also":["strony statusu","status page"]},{"id":"desk","g":"run","word":"Service desk","text":"Miejsce, do którego trafiają pytania i zgłoszenia od ludzi korzystających z twojej usługi. AI-gile przydziela każde do prośby, incydentu albo pomysłu i mówi, gdy wygląda na coś, co już zgłoszono.","also":["biuro obsługi","biurko","help desk","helpdesk"]},{"id":"svcrequest","g":"run","word":"Prośba o usługę","text":"Ktoś prosi o coś zwykłego, na przykład nowe konto albo trochę pomocy, zamiast zgłaszać, że coś jest zepsute. Czeka na swoją kolej; incydent idzie pierwszy.","also":["prośby o usługę","prośba"]},{"id":"incident","g":"run","word":"Incydent","text":"Coś, co właśnie teraz jest zepsute albo nie działa jak trzeba dla ludzi, którzy z tego korzystają, na przykład strona leży albo jest bardzo wolna. Karta 🔥 incydentu wskakuje na początek kolejki: najpierw trzeba to znowu uruchomić.","also":["incydenty","awaria"]},{"id":"major","g":"run","word":"Poważny incydent","text":"Duży incydent: dotyka wielu ludzi albo zagraża pieniądzom lub danym. Jeden przycisk rzuca na niego wszystkie zespoły (rój), budzi dyżurnego i co 30 minut prosi o informację o stanie.","also":["poważne incydenty","major incident"]},{"id":"oncall","g":"run","word":"Dyżur","text":"Bycie osobą, która reaguje, gdy coś się zepsuje, nawet w nocy. Każda usługa ma dyżurnego członka zespołu, którego budzi się jako pierwszego przy jej incydentach.","also":["dyżurny","on call","on-call","w pogotowiu"]},{"id":"replyby","g":"run","word":"Termin odpowiedzi","text":"Jak długo karta może czekać na pierwszą odpowiedź, na przykład godzinę przy incydencie. Potem dostaje czerwony zegar, żeby nic nie zostało po cichu zapomniane. Nazywa się to też docelowym czasem reakcji.","also":["terminy odpowiedzi","czas reakcji","docelowy czas reakcji"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"Krótka analiza po incydencie: co się stało, co pomogło i co zmienić, bez obwiniania kogokolwiek. Incydentu nie da się zamknąć bez niej.","also":["analiza poincydentalna","postmortem","przegląd po incydencie"]},{"id":"problem","g":"run","word":"Problem","text":"Ukryta przyczyna jednego lub kilku incydentów. Karta 🧩 problemu grupuje incydenty, które ciągle wracają, żeby przyczynę znaleźć i naprawić na dobre.","also":["problemy"],"noTip":1},{"id":"rootcause","g":"run","word":"Przyczyna źródłowa","text":"Prawdziwy powód, dla którego coś się zepsuło, a nie tylko to, co było widać. Napraw przyczynę źródłową, a incydent przestanie wracać.","also":["przyczyny źródłowe","root cause","pierwotna przyczyna"]},{"id":"workaround","g":"run","word":"Obejście","text":"Sposób, żeby wszystko działało, zanim będzie gotowa prawdziwa naprawa, na przykład restart czegoś, co się zawiesza. Zapisuje się je na karcie problemu, żeby nikt nie musiał wymyślać go od nowa.","also":["obejścia","workaround","rozwiązanie tymczasowe"]},{"id":"knownerror","g":"run","word":"Znany błąd","text":"Problem, którego przyczyna jest zrozumiana, ale nie jest jeszcze naprawiony, zwykle z zapisanym obejściem. 🧩 Znane błędy je wymienia, żeby każdy korzystał z obejścia, zamiast szukać od nowa.","also":["znane błędy","known error"]},{"id":"runbook","g":"run","word":"Runbook","text":"Instrukcja krok po kroku, jak naprawić znany rodzaj kłopotu, żeby za każdym razem robić to tak samo i szybko. Po dużym incydencie zespół może zaproponować taki runbook do Twojej akceptacji.","also":["runbooki","instrukcja postępowania","procedura"]},{"id":"ci","g":"run","word":"Element konfiguracji","text":"Jedna rzecz, od której zależy twoja usługa, na przykład serwer, domena, certyfikat, klucz albo dostawca. 🗂️ Elementy konfiguracji wymienia je dla każdej usługi, więc widać, czego dotyczy incydent i co trzeba odnowić albo zabezpieczyć kopią.","also":["elementy konfiguracji","elementów konfiguracji"]},{"id":"expiry","g":"run","word":"Data ważności","text":"Data, po której coś przestaje działać, jeśli go nie odnowisz, jak certyfikat bezpieczeństwa strony albo jej adres internetowy. AI-gile pilnuje tych dat i na 30 dni przed każdą robi jedną kartę o odnowienie, żeby nic nie stanęło niespodziewanie.","also":["daty ważności","wygaśnięcie","pilnowanie ważności"]},{"id":"backup","g":"run","word":"Kopia zapasowa","text":"Zapisana wcześniej kopia Twoich danych, na wypadek gdyby coś zginęło albo się uszkodziło. AI-gile codziennie robi kopię zapasową Twoich tablic.","also":["kopie zapasowe","backup","backupy"]},{"id":"restore","g":"run","word":"Przywracanie","text":"Odtwarzanie danych z kopii zapasowej. Kopia naprawdę się liczy dopiero wtedy, gdy wiesz, że da się ją przywrócić, więc warto to czasem sprawdzić.","also":["przywrócenie","przywrócone","restore"]},{"id":"svcreview","g":"run","word":"Przegląd usługi","text":"Spojrzenie wstecz na jeden miesiąc usługi: otwarte i naprawione incydenty, jak szybko ludzie dostali odpowiedź, dostępność i zużyte tokeny. Przegląd miesięczny pokazuje to dla każdej usługi.","also":["przeglądy usługi","przegląd miesięczny","przeglądy miesięczne"]},{"id":"accessreview","g":"run","word":"Przegląd dostępu","text":"Sprawdzanie co 90 dni, kto nadal ma dostęp: linki udostępniania, role znajomych oraz zapisane hasła i klucze. Każdy dostęp zachowujesz albo usuwasz, żeby stary nie zostawał na zawsze.","also":["przeglądy dostępu"]},{"id":"improvements","g":"run","word":"Lista usprawnień","text":"Wszystko, w czym zespół postanowił się poprawić, w jednym miejscu: sugestie z retrospektyw, działania z przeglądów i naprawy problemów, każde ze swoim statusem. Znajdziesz to pod 📈 Usprawnienia.","also":["listy usprawnień","usprawnienia"]},{"id":"tokencap","g":"run","word":"Limit tokenów","text":"Miesięczny limit tokenów, które mogą zużyć agenci usługi. Przy 80% dostajesz ostrzeżenie; przy 100% ich praca w tle czeka do następnego miesiąca albo do chwili, gdy podniesiesz limit.","also":["limity tokenów","miesięczny limit tokenów"]},{"id":"svcmgmt","g":"run","word":"Zarządzanie usługami","text":"Wszystko, co jest potrzebne, żeby usługa dzień po dniu była użyteczna i działała dla ludzi, którzy na niej polegają.","also":["service management","zarządzanie usługą"]},{"id":"itil","g":"run","word":"ITIL","text":"Powszechnie używany przewodnik po dobrym zarządzaniu usługami, obejmujący między innymi incydenty, problemy i zmiany. Nazwa kiedyś znaczyła IT Infrastructure Library."},{"id":"itsm","g":"run","word":"Zarządzanie usługami IT (ITSM)","text":"Prowadzenie technologii jako usługi dla ludzi, z jasnymi sposobami obsługi próśb, incydentów, zmian i usprawnień.","also":["ITSM","IT service management"]},{"id":"managed","g":"run","word":"Usługa zarządzana","text":"Usługa, którą ktoś inny prowadzi i się nią opiekuje za Ciebie, na podstawie umowy o tym, jak dobrze ma działać.","also":["usługi zarządzane","managed service","managed services"]},{"id":"svcowner","g":"run","word":"Właściciel usługi","text":"Osoba, która odpowiada za usługę jako całość: jak dobrze działa, ile kosztuje i jak się ulepsza.","also":["właściciele usług","service owner","service owners"]},{"id":"sla","g":"run","word":"Umowa o poziomie usług (SLA)","text":"Pisemna obietnica dla klientów, jak dobrze usługa będzie działać, na przykład „dostępna 99,9% czasu” albo „odpowiedź w godzinę”, często ze zwrotem pieniędzy, gdy nie zostanie dotrzymana.","also":["SLA","SLAs","service level agreement"]},{"id":"slo","g":"run","word":"Cel poziomu usług (SLO)","text":"Własny cel zespołu, jak dobrze usługa powinna działać w danym okresie, zwykle ustawiony trochę ostrzej niż SLA, dla bezpieczeństwa.","also":["SLO","SLOs","service level objective"]},{"id":"sli","g":"run","word":"Wskaźnik poziomu usług (SLI)","text":"Faktyczny pomiar, który porównujesz z celem, na przykład odsetek wejść, które załadowały się bez problemu.","also":["SLI","SLIs","service level indicator"]},{"id":"availability","g":"run","word":"Dostępność","text":"Czy ludzie mogą skorzystać z usługi, kiedy jej potrzebują, często mierzona jako uptime.","also":["wysoka dostępność","availability","high availability"]},{"id":"downtime","g":"run","word":"Przestój (downtime)","text":"Czas, gdy usługa nie działa albo jest wyłączona, zaplanowany lub nie.","also":["downtime","przerwa w działaniu","down time"]},{"id":"errorbudget","g":"run","word":"Budżet błędów","text":"Niewielka ilość awarii, na którą pozwala Twój cel niezawodności. Dopóki coś zostało, możesz ryzykować ze zmianami, a gdy się skończy, zwalniasz.","also":["error budget","error budgets"]},{"id":"outage","g":"run","word":"Awaria (outage)","text":"Czas, gdy usługa nie działa albo jest mocno zepsuta dla użytkowników.","also":["awarie","outage","outages"]},{"id":"degraded","g":"run","word":"Pogorszone działanie","text":"Działa, ale kiepsko: wolno albo nie wszystkie części działają.","also":["usługa działa gorzej","degraded","degraded service"]},{"id":"monitoring","g":"run","word":"Monitoring","text":"Automatyczne obserwowanie usługi cały czas, żeby problemy wyłapać, najlepiej zanim zauważą je użytkownicy.","also":["monitorowanie"]},{"id":"observability","g":"run","word":"Obserwowalność","text":"Jak dobrze potrafisz stwierdzić z zewnątrz, co się dzieje w środku systemu, na podstawie jego logów, liczb i śladów.","also":["observability","o11y"]},{"id":"log","g":"run","word":"Log (dziennik)","text":"Bieżący dziennik, który program prowadzi o tym, co robi, używany do ustalenia, co poszło nie tak.","also":["logi","dziennik","log","logs","logging"],"noTip":1},{"id":"trace","g":"run","word":"Trace (ślad)","text":"Zapis tego, jak jedno żądanie wędruje przez różne części systemu, krok po kroku, pokazujący, gdzie zwolniło.","also":["ślad","ślady","trace","traces","tracing","śledzenie"]},{"id":"latency","g":"run","word":"Opóźnienie (latency)","text":"Ile czasu mija, zanim coś odpowie, na przykład czekanie między kliknięciem a pojawieniem się strony.","also":["latency","czas odpowiedzi"]},{"id":"alert","g":"run","word":"Alert","text":"Automatyczna wiadomość, że coś wymaga uwagi, na przykład strona nie odpowiada.","also":["alerty","alarm","alerts","alerting"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Zmęczenie alertami","text":"Gdy alertów jest tyle, że ludzie zaczynają je ignorować, także te ważne.","also":["alert fatigue","alarm fatigue","zmęczenie alarmami"]},{"id":"dashboard","g":"run","word":"Dashboard (pulpit)","text":"Ekran pokazujący najważniejsze liczby i stany jednym spojrzeniem.","also":["dashboardy","pulpit","pulpit nawigacyjny","dashboards"],"noTip":1},{"id":"paging","g":"run","word":"Wywołanie dyżurnego (paging)","text":"Pilne dzwonienie do dyżurnego albo budzenie go z powodu problemu.","also":["paging","paged","pagowanie"]},{"id":"escalation","g":"run","word":"Eskalacja","text":"Zaangażowanie kogoś z większą wiedzą albo uprawnieniami, gdy sprawy nie da się załatwić na obecnym poziomie albo nie dość szybko.","also":["eskalować","eskalowanie","escalation","escalate","escalated"]},{"id":"triage","g":"run","word":"Triaż","text":"Szybkie sortowanie przychodzących spraw według pilności i ważności, żeby najgorsze załatwić najpierw.","also":["triage","segregacja zgłoszeń","triaged"]},{"id":"impact","g":"run","word":"Wpływ (impact)","text":"Jak bardzo coś dotyka ludzi: ilu i jak mocno.","noTip":1},{"id":"urgency","g":"run","word":"Pilność","text":"Jak szybko trzeba się czymś zająć. Wpływ i pilność razem ustalają priorytet.","noTip":1},{"id":"plevels","g":"run","word":"Poziomy priorytetu (P1, P2…)","text":"Etykiety mówiące, jak pilna jest sprawa. P1 jest najpoważniejsze i wymaga działania od razu.","also":["P1","P2","P3","P4","poziomy priorytetu"]},{"id":"queue","g":"run","word":"Kolejka zgłoszeń","text":"Lista próśb i incydentów czekających na podjęcie.","also":["kolejki zgłoszeń","ticket queue","ticket queues"]},{"id":"tiers","g":"run","word":"Pierwsza i druga linia","text":"Poziomy wsparcia: pierwsza linia odbiera zgłoszenie i naprawia proste rzeczy, druga ma głębszą wiedzę do trudniejszych. Mówi się też tier 1 i tier 2.","also":["pierwsza linia","druga linia","wsparcie pierwszej linii","first-line support","tier 1","tier 2"]},{"id":"ic","g":"run","word":"Dowódca incydentu","text":"Jedna osoba, która kieruje reakcją na incydent, żeby wszyscy wiedzieli, kto decyduje i kto co robi.","also":["dowódcy incydentu","incident commander","incident commanders"]},{"id":"responsetime","g":"run","word":"Czas reakcji","text":"Ile czasu mija, zanim ktoś po raz pierwszy zajmie się prośbą albo incydentem.","also":["czasy reakcji","response time","response times"]},{"id":"resolution","g":"run","word":"Czas rozwiązania","text":"Ile czasu zajmuje całkowite załatwienie prośby albo incydentu, od zgłoszenia do naprawy.","also":["czasy rozwiązania","resolution time","resolution times","time to resolve"]},{"id":"mttr","g":"run","word":"Średni czas przywrócenia (MTTR)","text":"Średnio, ile trwa przywrócenie działania usługi po awarii. MTTR może znaczyć trochę różne rzeczy, więc zaznacz, co dokładnie mierzysz.","also":["MTTR","mean time to recover","mean time to restore"]},{"id":"mtbf","g":"run","word":"Średni czas między awariami (MTBF)","text":"Średnio, jak długo usługa działa, zanim coś się zepsuje.","also":["MTBF","mean time between failures"]},{"id":"cmdb","g":"run","word":"Baza konfiguracji (CMDB)","text":"Lista wszystkich elementów konfiguracji i tego, jak są połączone, żeby widzieć, co od czego zależy.","also":["CMDB","configuration management database"]},{"id":"asset","g":"run","word":"Zasób (asset)","text":"Wszystko wartościowe, co posiadasz albo za co płacisz, by prowadzić usługę, na przykład laptop, licencja na oprogramowanie albo domena.","also":["zasoby","asset","assets"],"noTip":1},{"id":"capplan","g":"run","word":"Planowanie zasobów (capacity planning)","text":"Dbanie, żeby było dość mocy obliczeniowej, miejsca na dane i ludzi na to, co nadchodzi.","also":["planowanie pojemności","capacity planning","capacity plan"]},{"id":"scaling","g":"run","word":"Skalowanie","text":"Radzenie sobie z większą liczbą użytkowników przez dodanie mocy jednej maszynie (skalowanie w górę) albo dołożenie kolejnych maszyn (skalowanie w poziomie).","also":["skalować","scaling","scale up","scale out","scaling up","scaling out"]},{"id":"bcp","g":"run","word":"Ciągłość działania","text":"Plany utrzymania najważniejszych rzeczy, gdy stanie się coś dużego, na przykład utrata biura, kluczowego dostawcy albo komputerów.","also":["plan ciągłości działania","business continuity","business continuity plan"]},{"id":"dr","g":"run","word":"Odtwarzanie po awarii (DR)","text":"Plan i narzędzia do przywrócenia usługi po czymś poważnym, na przykład utracie całego centrum danych.","also":["DR","disaster recovery","odtwarzanie po katastrofie"]},{"id":"rto","g":"run","word":"Docelowy czas odtworzenia (RTO)","text":"Najdłuższy czas, przez jaki usługa może nie działać po katastrofie, zanim musi znów działać.","also":["RTO","recovery time objective"]},{"id":"rpo","g":"run","word":"Docelowy punkt odtworzenia (RPO)","text":"Ile ostatnich danych możesz sobie pozwolić stracić, mierzone w czasie. RPO równe jednej godzinie oznacza kopie zapasowe co najmniej co godzinę.","also":["RPO","recovery point objective"]},{"id":"redundancy","g":"run","word":"Redundancja","text":"Posiadanie gotowych zapasowych elementów, jak drugi serwer, żeby jedna awaria nie zatrzymała usługi.","also":["nadmiarowość","redundancy"]},{"id":"failover","g":"run","word":"Failover (przełączenie awaryjne)","text":"Samoczynne przełączenie na zapasowy system, gdy zwykły przestanie działać.","also":["failover","przełączenie awaryjne","fail over"]},{"id":"spof","g":"run","word":"Pojedynczy punkt awarii","text":"Jedna część, która po zepsuciu pociąga za sobą wszystko, bo nie ma zapasowej.","also":["SPOF","single point of failure","single points of failure"]},{"id":"maintwin","g":"run","word":"Okno serwisowe","text":"Zaplanowany czas, gdy usługa może być wstrzymana albo wolna z powodu prac konserwacyjnych, zapowiedziany użytkownikom z góry.","also":["okna serwisowe","przerwa techniczna","maintenance window","maintenance windows","planned maintenance"]},{"id":"handover","g":"run","word":"Przekazanie","text":"Przekazanie pracy, wiedzy i odpowiedzialności innej osobie albo zespołowi, żeby nic nie przepadło.","also":["przekazania","handover","handovers"]},{"id":"kb","g":"run","word":"Baza wiedzy","text":"Zbiór artykułów pomocy i odpowiedzi, dla użytkowników i dla zespołu.","also":["bazy wiedzy","knowledge base","knowledge bases"]},{"id":"csat","g":"run","word":"Zadowolenie klienta (CSAT)","text":"Ocena od użytkowników, jak bardzo są zadowoleni, zbierana zwykle po zamknięciu prośby.","also":["CSAT","customer satisfaction"]},{"id":"supplier","g":"run","word":"Dostawca","text":"Zewnętrzna firma, na której polegasz, jak Twój dostawca hostingu. Mówi się też vendor albo strona trzecia.","also":["dostawcy","vendor","vendors","third party","podmiot zewnętrzny","supplier","suppliers"],"noTip":1},{"id":"retire","g":"run","word":"Wycofanie usługi","text":"Wyłączenie usługi na dobre, bezpiecznie: poinformowanie użytkowników, zajęcie się danymi i dostępami oraz zatrzymanie kosztów.","also":["wycofywanie usługi","service retirement","retiring a service"]},{"id":"eol","g":"run","word":"Koniec wsparcia (EOL)","text":"Gdy produkt przestaje dostawać aktualizacje albo wsparcie od producenta, więc trzeba go wymienić.","also":["EOL","end-of-life","end of life"]},{"id":"cybersec","g":"sec","word":"Cyberbezpieczeństwo","text":"Ochrona systemów i danych przed włamaniem, kradzieżą i uszkodzeniem.","also":["bezpieczeństwo cyfrowe","cybersecurity","cyber security"]},{"id":"authn","g":"sec","word":"Uwierzytelnianie","text":"Sprawdzanie, kim ktoś jest, zwykle hasłem albo kodem. Często skracane do authn.","also":["authn","authentication"]},{"id":"authz","g":"sec","word":"Autoryzacja","text":"Sprawdzanie, co ktoś może robić, gdy już wiadomo, kim jest. Często skracane do authz.","also":["authz","authorisation","authorization","uprawnienia"]},{"id":"mfa","g":"sec","word":"Uwierzytelnianie wieloskładnikowe (MFA)","text":"Logowanie z dwoma lub więcej dowodami, na przykład hasło plus kod na telefonie. Mówi się też dwuskładnikowe (2FA).","also":["MFA","2FA","dwuskładnikowe","two-factor","two-factor authentication","weryfikacja dwuetapowa"]},{"id":"sso","g":"sec","word":"Jednokrotne logowanie (SSO)","text":"Zalogowanie się raz, żeby wejść do wielu systemów, jak używanie konta służbowego wszędzie.","also":["SSO","single sign-on"]},{"id":"pwmgr","g":"sec","word":"Menedżer haseł","text":"Aplikacja, która tworzy silne hasła i pamięta je za Ciebie.","also":["menedżery haseł","password manager","password managers"]},{"id":"secret","g":"sec","word":"Sekret","text":"Hasło, klucz albo inny prywatny kod, którego program używa, żeby się do czegoś dostać. Nigdy nie wolno go udostępniać ani wpisywać w kod.","also":["sekrety","secret","secrets"],"noTip":1},{"id":"apikey","g":"sec","word":"Klucz API","text":"Tajny kod, który pozwala programowi korzystać z API innej usługi i pokazuje, kto z niego korzysta (i za nie płaci).","also":["klucze API","API key","API keys"]},{"id":"accesstoken","g":"sec","word":"Token dostępu","text":"Tymczasowa przepustka, która dowodzi, że program może wejść, więc nie potrzebuje za każdym razem Twojego hasła. To nie to samo, co token AI.","also":["tokeny dostępu","access token","access tokens"]},{"id":"encryption","g":"sec","word":"Szyfrowanie","text":"Zamienianie informacji w nieczytelny ciąg znaków, tak żeby tylko ktoś z właściwym kluczem mógł je przeczytać.","also":["szyfrować","zaszyfrowane","encryption","encrypted","encrypt"]},{"id":"https","g":"sec","word":"HTTPS","text":"Bezpieczny sposób, w jaki podróżują strony internetowe, widoczny po kłódce w przeglądarce, żeby nikt po drodze nie mógł ich czytać ani zmieniać."},{"id":"cert","g":"sec","word":"Certyfikat SSL/TLS","text":"Cyfrowy dowód tożsamości, który pozwala stronie udowodnić, kim jest, i używać HTTPS. Wygasa, więc trzeba go odnawiać.","also":["certyfikat TLS","certyfikat SSL","certyfikat","certyfikaty","TLS certificate","SSL certificate","certificate","certificates"]},{"id":"permissions","g":"sec","word":"Uprawnienia","text":"Zasady, kto może co widzieć albo zmieniać.","also":["uprawnienie","zezwolenia","permissions","permission"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Zasada najmniejszych uprawnień","text":"Dawanie każdej osobie albo programowi tylko takiego dostępu, jakiego naprawdę potrzebuje, i tylko na tak długo, jak potrzebuje.","also":["najmniejsze uprawnienia","least privilege","principle of least privilege"]},{"id":"rbac","g":"sec","word":"Kontrola dostępu oparta na rolach (RBAC)","text":"Nadawanie dostępu według roli, na przykład oglądający albo edytujący, zamiast osoba po osobie.","also":["RBAC","dostęp oparty na rolach","role-based access"]},{"id":"vuln","g":"sec","word":"Podatność","text":"Słabość, którą ktoś mógłby wykorzystać, żeby się włamać albo wyrządzić szkodę.","also":["podatności","luka w zabezpieczeniach","vulnerability","vulnerabilities"]},{"id":"zeroday","g":"sec","word":"Zero-day","text":"Słabość znana atakującym, zanim twórcy zdążyli ją w ogóle naprawić.","also":["zero-days","zero day","luka zero-day"]},{"id":"malware","g":"sec","word":"Malware (złośliwe oprogramowanie)","text":"Szkodliwe oprogramowanie, jak wirusy, stworzone do niszczenia, szpiegowania albo kradzieży.","also":["malware","złośliwe oprogramowanie"]},{"id":"ransomware","g":"sec","word":"Ransomware","text":"Złośliwe oprogramowanie, które blokuje Twoje pliki i żąda pieniędzy za ich odblokowanie. Dobre kopie zapasowe to najlepsza obrona.","also":["oprogramowanie wymuszające okup","atak ransomware","ransomware attack"]},{"id":"phishing","g":"sec","word":"Phishing","text":"Fałszywe wiadomości, które próbują Cię oszukać, żeby wyłudzić hasła albo pieniądze albo nakłonić Cię do otwarcia czegoś szkodliwego.","also":["wyłudzanie danych","fałszywy mail","phishing email","phishing emails"]},{"id":"socialeng","g":"sec","word":"Inżynieria społeczna","text":"Oszukiwanie ludzi, a nie komputerów, żeby dali dostęp, na przykład fałszywy telefon od „pomocy technicznej”."},{"id":"firewall","g":"sec","word":"Zapora sieciowa (firewall)","text":"Strażnik, który decyduje, jaki ruch sieciowy może wejść albo wyjść.","also":["firewall","zapora","firewalle","firewalls"]},{"id":"vpn","g":"sec","word":"VPN","text":"Skrót od „virtual private network”: prywatne, zaszyfrowane połączenie przez internet, często używane do bezpiecznego dostępu do systemów w pracy.","also":["wirtualna sieć prywatna","virtual private network"]},{"id":"ddos","g":"sec","word":"Atak odmowy usługi (DoS, DDoS)","text":"Zalewanie usługi tak dużym fałszywym ruchem, że prawdziwi ludzie nie mogą z niej korzystać. DDoS oznacza, że pochodzi z wielu komputerów naraz.","also":["DoS","DDoS","denial of service","atak DDoS","DDoS attack"]},{"id":"pentest","g":"sec","word":"Test penetracyjny (pentest)","text":"Wynajęcie życzliwych ekspertów, którzy próbują się włamać, żeby słabości znaleźć, zanim znajdą je prawdziwi atakujący.","also":["pentest","testy penetracyjne","pen test","pen testing","penetration testing"]},{"id":"audit","g":"sec","word":"Audyt bezpieczeństwa","text":"Dokładne sprawdzenie, jak dobrze coś jest chronione, względem listy dobrych praktyk.","also":["audyty bezpieczeństwa","security audit","security audits"]},{"id":"threatmodel","g":"sec","word":"Modelowanie zagrożeń","text":"Przemyślenie, kto mógłby coś zaatakować, jak, i co zrobisz, żeby go powstrzymać.","also":["model zagrożeń","threat modelling","threat model","threat modeling"]},{"id":"breach","g":"sec","word":"Wyciek danych","text":"Gdy prywatne informacje trafiają do osób, które nie powinny ich mieć, albo zostają zgubione lub zmienione bez zgody.","also":["naruszenie danych","wycieki danych","data breach","data breaches"]},{"id":"pii","g":"sec","word":"Dane osobowe","text":"Wszelkie informacje o osobie, którą można zidentyfikować, jak imię i nazwisko, adres e-mail albo lokalizacja. Mówi się też PII.","also":["PII","personal data","personally identifiable information"]},{"id":"gdpr","g":"sec","word":"RODO (GDPR)","text":"Europejskie prawo o danych osobowych (Wielka Brytania ma własną wersję): zbieraj tylko to, czego potrzebujesz, trzymaj to bezpiecznie i pozwól ludziom zobaczyć lub usunąć ich dane.","also":["RODO","GDPR","General Data Protection Regulation"]},{"id":"dataprot","g":"sec","word":"Ochrona danych","text":"Dbanie o dane osobowe w odpowiedni sposób i zgodnie z prawem.","also":["ochrona danych osobowych","data protection","data protection law"]},{"id":"privacypolicy","g":"sec","word":"Polityka prywatności","text":"Publiczna strona mówiąca, jakie dane osobowe zbierasz, po co i co z nimi robisz.","also":["klauzula informacyjna","privacy policy","privacy statement","privacy notice"]},{"id":"consent","g":"sec","word":"Zgoda","text":"Wyraźne, dobrowolne „tak” osoby na wykorzystanie jej danych w określony sposób. Może ją cofnąć w każdej chwili.","also":["opt-in","consent","zgoda na przetwarzanie"],"noTip":1},{"id":"cookie","g":"sec","word":"Ciasteczko (cookie)","text":"Mały plik, który strona zapisuje w przeglądarce, żeby coś zapamiętać, na przykład to, że się zalogowano. Niektóre wymagają najpierw Twojej zgody.","also":["ciasteczka","cookie","cookies","pliki cookie"],"noTip":1},{"id":"minimisation","g":"sec","word":"Minimalizacja danych","text":"Zbieranie i przechowywanie tylko tych danych osobowych, które naprawdę są potrzebne do zadania.","also":["data minimisation","data minimization"]},{"id":"retention","g":"sec","word":"Przechowywanie danych","text":"Jak długo dane są trzymane, zanim zostaną usunięte. Trzymanie ich nie dłużej, niż trzeba, jest bezpieczniejsze i często wymagane prawem.","also":["okres przechowywania","retencja danych","data retention","retention period"]},{"id":"anon","g":"sec","word":"Anonimizacja","text":"Zmiana danych tak, żeby na ich podstawie nie dało się już rozsądnie nikogo zidentyfikować.","also":["zanonimizowane","dane anonimowe","anonymisation","anonymised","anonymization","anonymous data"]},{"id":"pseudo","g":"sec","word":"Pseudonimizacja","text":"Zastąpienie imion i innych szczegółów kodami, z kluczem trzymanym osobno, żeby je z powrotem połączyć. To nadal są dane osobowe.","also":["spseudonimizowane","pseudonymisation","pseudonymised","pseudonymization"]},{"id":"dpa","g":"sec","word":"Umowa powierzenia przetwarzania danych (DPA)","text":"Umowa mówiąca, jak dostawca może obchodzić się z danymi osobowymi w Twoim imieniu.","also":["DPA","umowa powierzenia","data processing agreement"]},{"id":"dpia","g":"sec","word":"Ocena skutków dla ochrony danych (DPIA)","text":"Dokładne przyjrzenie się przed startem, jak plan wykorzystania danych osobowych może wpłynąć na ludzi i jak zmniejszyć ryzyka.","also":["DPIA","ocena skutków","data protection impact assessment"]},{"id":"auditlog","g":"sec","word":"Dziennik audytu","text":"Zapis tego, kto co zrobił i kiedy, żeby można było później sprawdzić działania.","also":["dzienniki audytu","ślad audytowy","audit log","audit logs","audit trail"]},{"id":"compliance","g":"sec","word":"Zgodność z przepisami (compliance)","text":"Przestrzeganie praw, zasad i norm, które Cię dotyczą, i umiejętność wykazania, że to robisz.","also":["compliance","zgodność","compliant"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"Dobrze znana międzynarodowa norma zarządzania bezpieczeństwem informacji. Firmy mogą się według niej certyfikować.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"Amerykański raport, sprawdzony przez zewnętrznych audytorów, pokazujący, że firma należycie dba o dane klientów.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Agent","text":"AI, która sama pracuje nad zadaniem: czyta kod, wprowadza zmiany, uruchamia sprawdzenia i zgłasza wynik. Jej praca nadal jest sprawdzana.","also":["agenci"]},{"id":"token","g":"ai","word":"Token","text":"Małe kawałki tekstu, które AI czyta i pisze, każdy to mniej więcej trzy czwarte słowa. Zużycie AI liczy się w tokenach, więc mniej tokenów zostawia więcej z Twojego planu.","also":["tokeny"]},{"id":"hook","g":"ai","word":"Hook","text":"Małe polecenie, które uruchamia się samo w ustalonym momencie, na przykład gdy startuje sesja AI, żeby zespół usłyszał Twoje komentarze.","also":["hooki","haki"]},{"id":"ai","g":"ai","word":"Sztuczna inteligencja (AI)","text":"Systemy komputerowe, które robią rzeczy, do których zwykle potrzeba człowieka, jak pisanie, odpowiadanie na pytania albo rozpoznawanie obrazów.","also":["AI","SI","artificial intelligence"],"noTip":1},{"id":"ml","g":"ai","word":"Uczenie maszynowe (ML)","text":"Sposób, w jaki komputery uczą się wzorców z wielu przykładów, zamiast dostawać dokładne reguły.","also":["ML","machine learning"]},{"id":"model","g":"ai","word":"Model","text":"Wytrenowany „mózg” systemu AI, zbudowany przez uczenie się na ogromnej liczbie przykładów. Modele różnią się umiejętnościami, szybkością i ceną.","also":["modele","model AI","models","AI model"],"noTip":1},{"id":"llm","g":"ai","word":"Duży model językowy (LLM)","text":"Model AI wytrenowany na ogromnych ilościach tekstu, dzięki czemu potrafi czytać i pisać teksty.","also":["LLM","LLMs","large language model"]},{"id":"genai","g":"ai","word":"Generatywna AI","text":"AI, która tworzy nowe rzeczy, jak teksty, obrazy albo kod, a nie tylko je sortuje czy rozpoznaje.","also":["GenAI","generative AI"]},{"id":"chatbot","g":"ai","word":"Chatbot","text":"Program, z którym rozmawiasz zwykłym językiem, pisząc albo mówiąc.","also":["chatboty","czatbot","chatbots"]},{"id":"prompt","g":"ai","word":"Prompt","text":"To, co dajesz AI: pytanie albo instrukcje oraz wszystko, co jej podasz. Jaśniejsze prompty zwykle dają lepsze odpowiedzi.","also":["prompty","polecenie dla AI","prompts"]},{"id":"prompteng","g":"ai","word":"Inżynieria promptów","text":"Umiejętność pisania promptów, które dają rzetelne, przydatne wyniki.","also":["prompt engineering","pisanie promptów"]},{"id":"sysprompt","g":"ai","word":"Prompt systemowy","text":"Instrukcje w tle, które AI dostaje przed rozpoczęciem rozmowy i które ustalają jej rolę oraz zasady. Ważą więcej niż to, co wpiszesz.","also":["prompty systemowe","system prompt","system prompts","system instruction","system instructions","instrukcja systemowa"]},{"id":"context","g":"ai","word":"Kontekst","text":"Wszystko, co AI widzi podczas pracy: instrukcje, Twoje wiadomości, pliki, które przeczytała, i wcześniejsze odpowiedzi.","noTip":1},{"id":"ctxwin","g":"ai","word":"Okno kontekstu","text":"Ile AI może mieć w głowie naraz, mierzone w tokenach. Po przekroczeniu tej granicy starsze części są pomijane albo streszczane.","also":["okna kontekstu","context window","context windows"]},{"id":"session","g":"ai","word":"Sesja","text":"Jedna robocza rozmowa z AI, od początku do końca. Nowa sesja zaczyna się ze świeżą pamięcią.","also":["sesje","session","sessions"],"noTip":1},{"id":"memory","g":"ai","word":"Pamięć","text":"Notatki, które AI trzyma między sesjami, żeby pamiętała Twoje preferencje i dawne decyzje.","noTip":1},{"id":"hallucination","g":"ai","word":"Halucynacja","text":"Gdy AI mówi coś, co brzmi pewnie, ale jest zmyślone lub błędne. Ważne fakty sprawdzaj.","also":["halucynacje","halucynować","hallucination","hallucinations","hallucinate","hallucinates"]},{"id":"training","g":"ai","word":"Trenowanie","text":"Uczenie modelu przez pokazywanie mu ogromnej liczby przykładów, zanim ktokolwiek zacznie go używać.","also":["trening","wytrenowany","training","trained"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Dane treningowe","text":"Przykłady, z których model się uczył. Jego wiedza kończy się w dniu, w którym te dane zebrano.","also":["zbiór treningowy","training data","training set"]},{"id":"cutoff","g":"ai","word":"Granica wiedzy","text":"Data, na której kończy się wbudowana wiedza AI. O późniejszych rzeczach nie wie, chyba że je sprawdzi.","also":["data odcięcia wiedzy","knowledge cutoff","training cutoff"]},{"id":"finetune","g":"ai","word":"Dostrajanie (fine-tuning)","text":"Dodatkowe trenowanie istniejącego modelu na Twoich przykładach, żeby był lepszy w jednym konkretnym zadaniu.","also":["fine-tuning","dostrajać","fine-tune","fine-tuned","fine tuning"]},{"id":"inference","g":"ai","word":"Wnioskowanie (inference)","text":"Model AI faktycznie używany do odpowiedzi na coś, w odróżnieniu od trenowania.","also":["inference","inferencja","model inference"]},{"id":"tooluse","g":"ai","word":"Korzystanie z narzędzi","text":"AI, która potrafi coś robić, a nie tylko mówić: uruchamiać polecenia, czytać pliki albo szukać w sieci, przez narzędzia, które daje jej aplikacja.","also":["tool use","wywoływanie narzędzi","tool calling","tool call","tool calls"]},{"id":"subagent","g":"ai","word":"Subagent","text":"Pomocnicza AI, której główna AI zleca mniejsze zadanie i od której dostaje wynik.","also":["subagenci","subagents","sub-agent"]},{"id":"multiagent","g":"ai","word":"Wieloagentowość","text":"Kilka AI pracuje razem nad jedną sprawą, każda ze swoją częścią, jak mały zespół.","also":["multi-agent","system wieloagentowy","multi-agent system"]},{"id":"autonomy","g":"ai","word":"Autonomia","text":"Ile AI może zrobić sama, zanim musi zapytać człowieka.","also":["autonomous","autonomiczny"]},{"id":"hitl","g":"ai","word":"Człowiek w pętli","text":"Utrzymywanie człowieka w grze, żeby w kluczowych momentach sprawdzał albo zatwierdzał to, co robi AI. W AI-gile to Ty.","also":["human in the loop","human-in-the-loop","HITL"]},{"id":"guardrails","g":"ai","word":"Bariery ochronne (guardrails)","text":"Ograniczenia i sprawdzenia, które chronią działania AI, na przykład wymóg zatwierdzenia, zanim cokolwiek pójdzie na żywo. Zmniejszają ryzyko pomyłek, ale ich nie wykluczają.","also":["guardrails","guardrail","barierki"]},{"id":"rag","g":"ai","word":"RAG (generowanie wsparte wyszukiwaniem)","text":"Pozwalanie AI sprawdzić coś w Twoich dokumentach, zanim odpowie, żeby jej odpowiedzi opierały się na Twoich faktach.","also":["RAG","retrieval-augmented generation","retrieval augmented generation"]},{"id":"embedding","g":"ai","word":"Embedding (osadzenie)","text":"Zamiana tekstu na listę liczb, która oddaje jego znaczenie, żeby komputer mógł znajdować rzeczy o podobnym sensie.","also":["embeddingi","osadzenia","embedding","embeddings"]},{"id":"vectordb","g":"ai","word":"Wektorowa baza danych","text":"Baza zbudowana do przeszukiwania takich list liczb (embeddingów), żeby znajdować materiały o podobnym znaczeniu.","also":["wektorowe bazy danych","vector database","vector databases","vector store"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"Wspólny sposób podłączania narzędzi i źródeł danych do aplikacji z AI, żeby AI mogła z nich korzystać.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Temperatura","text":"Ustawienie, jak odważne są odpowiedzi AI. Niska daje stabilniejsze, bardziej przewidywalne odpowiedzi, wysoka bardziej zróżnicowane. Żadna nie sprawia, że zawsze ma rację.","also":["temperature","temperatura modelu","model temperature"],"noTip":1},{"id":"multimodal","g":"ai","word":"Multimodalny","text":"Potrafiący pracować z więcej niż jednym rodzajem informacji, jak tekst, obrazy i dźwięk.","also":["multimodalność","multimodal","multi-modal"]},{"id":"evals","g":"ai","word":"Ewaluacja (eval)","text":"Zaplanowany test tego, jak dobrze AI radzi sobie na wybranych przykładach, żeby porównywać modele albo prompty.","also":["eval","evals","ewaluacje"]},{"id":"bias","g":"ai","word":"Uprzedzenie (bias)","text":"Gdy AI (albo człowiek) niesprawiedliwie przechyla się w jedną stronę, często przez to, z czego się uczyła.","also":["bias","stronniczość","biased"],"noTip":1},{"id":"responsible","g":"ai","word":"Odpowiedzialna AI","text":"Używanie AI uczciwie, bezpiecznie i rzetelnie, tak by za wyniki nadal odpowiadali ludzie.","also":["etyczna AI","responsible AI","ethical AI"]},{"id":"injection","g":"ai","word":"Prompt injection","text":"Sztuczka, w której ukryte instrukcje na stronie albo w pliku próbują sprawić, żeby AI zrobiła coś, o co użytkownik nie prosił.","also":["wstrzyknięcie promptu","prompt injections"]},{"id":"ratelimit","g":"ai","word":"Limit zapytań (rate limit)","text":"Górna granica liczby próśb, które możesz wysłać do usługi w danym czasie. Po przekroczeniu musisz poczekać.","also":["rate limit","limity zapytań","rate limits","rate limited"]},{"id":"usagelimit","g":"ai","word":"Limit zużycia","text":"Na ile pracy AI pozwala Twój plan w danym okresie. Potem praca się wstrzymuje albo kosztuje więcej.","also":["limity zużycia","usage limit","usage limits"]},{"id":"vibe","g":"ai","word":"Vibe coding","text":"Budowanie oprogramowania głównie przez opisanie AI, czego chcesz, i pozwolenie jej napisać kod.","also":["vibe-coding"]},{"id":"budget","g":"money","word":"Budżet","text":"Kwota pieniędzy odłożona na coś.","also":["budżety","budget","budgets"],"noTip":1},{"id":"costest","g":"money","word":"Szacunek kosztów","text":"Najlepsze przypuszczenie, ile coś będzie kosztować, zanim zaczniesz.","also":["kosztorys","cost estimate","cost estimates"]},{"id":"roi","g":"money","word":"Zwrot z inwestycji (ROI)","text":"Ile odzyskujesz w porównaniu z tym, ile włożono. Jeśli wynik jest dodatni, było warto.","also":["ROI","return on investment"]},{"id":"tco","g":"money","word":"Całkowity koszt posiadania (TCO)","text":"Całość tego, ile coś naprawdę kosztuje przez cały okres użytkowania, nie tylko cena zakupu: utrzymanie, wsparcie, ulepszenia i na końcu wycofanie.","also":["TCO","total cost of ownership"]},{"id":"capex","g":"money","word":"CapEx i OpEx","text":"CapEx to pieniądze wydane z góry na rzeczy, które zatrzymujesz; OpEx to bieżące wydatki, jak miesięczne rachunki.","also":["CapEx","OpEx","wydatki kapitałowe","wydatki operacyjne","capital expenditure","operating expenditure"]},{"id":"subscription","g":"money","word":"Subskrypcja","text":"Płacenie regularnie, zwykle co miesiąc albo co rok, żeby dalej z czegoś korzystać.","also":["subskrypcje","abonament","subscription","subscriptions"],"noTip":1},{"id":"saas","g":"money","word":"Oprogramowanie jako usługa (SaaS)","text":"Oprogramowanie, z którego korzystasz online i za które płacisz subskrypcją, a twórca prowadzi je za Ciebie.","also":["SaaS","software as a service"]},{"id":"payg","g":"money","word":"Płatność za użycie","text":"Płacenie tylko za to, z czego korzystasz, jak w chmurze obliczeniowej albo przy tokenach AI.","also":["pay as you go","pay-as-you-go","usage-based pricing","rozliczanie za zużycie"]},{"id":"overage","g":"money","word":"Przekroczenie planu (overage)","text":"Zużycie ponad to, co obejmuje Twój plan, co może kosztować dodatkowo.","also":["overage","overages","overage charges","opłaty za przekroczenie"]},{"id":"billingalert","g":"money","word":"Alert rozliczeniowy","text":"Wiadomość, gdy wydatki albo zużycie osiągną wybrany przez Ciebie poziom. Ostrzega, ale nie zawsze zatrzymuje dalsze opłaty.","also":["alerty rozliczeniowe","billing alert","billing alerts","spending alert"]},{"id":"freetier","g":"money","word":"Darmowy poziom","text":"Darmowy poziom płatnej usługi, z ograniczeniami. Przydatny na początek.","also":["plan darmowy","free tier","free plan"]},{"id":"pricing","g":"money","word":"Plan cenowy","text":"Różne pakiety, które sprzedaje usługa, każdy z własną ceną i limitami.","also":["plany cenowe","cennik","pricing plan","pricing plans","price plan"]},{"id":"licence","g":"money","word":"Licencja","text":"Zasady, jak wolno Ci używać, kopiować, zmieniać albo udostępniać coś, co zrobił ktoś inny, jak oprogramowanie, czcionki czy obrazy.","also":["licencje","licence","licences","license","licenses"],"noTip":1},{"id":"opensource","g":"money","word":"Open source","text":"Oprogramowanie, którego kod każdy może czytać, używać i często zmieniać za darmo, według zasad jego licencji.","also":["otwarte oprogramowanie","otwarty kod","open-source","open source software","OSS"]},{"id":"osslicence","g":"money","word":"Licencja open source","text":"Zasady dołączone do kodu open source. Niektóre pozwalają robić prawie wszystko (jak MIT), inne proszą, żeby swoje zmiany też udostępnić (jak GPL).","also":["licencje open source","licencja MIT","open source licence","open source licences","MIT licence","GPL"]},{"id":"proprietary","g":"money","word":"Własnościowe","text":"Należące do firmy i niedostępne do swobodnego kopiowania czy zmieniania. Przeciwieństwo open source.","also":["oprogramowanie własnościowe","proprietary","proprietary software","zamknięte oprogramowanie"]},{"id":"copyright","g":"money","word":"Prawa autorskie","text":"Prawo twórcy do kontrolowania kopii swojej pracy, także kodu i tekstów.","also":["copyright","autorskie prawa majątkowe","copyrighted"],"noTip":1},{"id":"ip","g":"money","word":"Własność intelektualna (IP)","text":"Pomysły i twory, które prawo uznaje za czyjąś własność, jak kod, projekty, nazwy i logo.","also":["IP","intellectual property"]},{"id":"tos","g":"money","word":"Regulamin","text":"Zasady, na które się zgadzasz, korzystając z usługi.","also":["warunki korzystania","warunki świadczenia usług","terms of service","terms and conditions","terms of use"]},{"id":"contract","g":"money","word":"Umowa","text":"Pisemne porozumienie między dwiema stronami, które prawo będzie egzekwować.","also":["umowy","kontrakt","contract","contracts"],"noTip":1},{"id":"sow","g":"money","word":"Zakres prac (SOW)","text":"Dokument, który dokładnie określa, jaka praca zostanie wykonana, do kiedy i za ile.","also":["SOW","statement of work","opis przedmiotu zamówienia"]},{"id":"fixedprice","g":"money","word":"Stała cena","text":"Uzgodniona cena za całe zlecenie, niezależnie od tego, jak długo potrwa.","also":["ryczałt","fixed price","fixed-price"]},{"id":"tm","g":"money","word":"Rozliczenie za czas i materiały","text":"Płacenie za faktycznie przepracowane godziny i faktycznie użyte rzeczy, a nie za ustaloną cenę.","also":["T&M","time and materials","rozliczenie godzinowe"]},{"id":"invoice","g":"money","word":"Faktura","text":"Rachunek z prośbą o zapłatę za wykonaną pracę albo dostarczone towary.","also":["faktury","invoice","invoices"],"noTip":1},{"id":"lockin","g":"money","word":"Uzależnienie od dostawcy (lock-in)","text":"Gdy odejście od dostawcy jest tak trudne albo kosztowne, że praktycznie nie da się od niego uwolnić.","also":["lock-in","vendor lock-in","uzależnienie od dostawcy"]},{"id":"procurement","g":"money","word":"Zakupy i zamówienia","text":"Proces wybierania dostawców i kupowania od nich.","also":["procurement","zaopatrzenie","zakupy"]},{"id":"servicecredit","g":"money","word":"Rekompensata (service credit)","text":"Zwrot pieniędzy albo zniżka, które dostajesz, gdy dostawca nie dotrzyma SLA.","also":["rekompensata za SLA","service credit","service credits"]}]}};
